package com.clansocket;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public final class ClanSocketPluginTest
{
	private ClanSocketPluginTest() {
	}

	@SuppressWarnings({"unchecked", "varargs"})
	public static void main(final String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ClanSocketPlugin.class);
		RuneLite.main(args);
	}
}

package com.clansocket;

import javax.inject.Inject;

import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import com.clansocket.chat.GameChatEmitter;
import com.clansocket.config.ConfigEventBridge;
import com.clansocket.panel.PanelLifecycle;
import com.clansocket.protocol.common.Payload;
import com.clansocket.transport.LifecycleListeners;
import com.google.inject.Provides;

import lombok.extern.slf4j.Slf4j;

@Slf4j
@PluginDescriptor(name = "ClanSocket", description = "Streams realtime clan + gameplay telemetry over WebSocket.", tags = {
        "clan", "telemetry", "tracker", "dashboard", "websocket", "chat"})
public class ClanSocketPlugin extends Plugin
{
	@Inject
	private ClanSocketConfig config;
	@Inject
	private ClanSocket socket;
	@Inject
	private CSTrackerRegistry trackers;
	@Inject
	private GameChatEmitter chatEmitter;
	@Inject
	private EventBus eventBus;
	@Inject
	private ClientThread clientThread;
	@Inject
	private PanelLifecycle panelLifecycle;
	@Inject
	private ConfigEventBridge configEventBridge;
	@Inject
	private LifecycleListeners listeners;

	@Override
	protected void startUp()
	{
		log.info("ClanSocket started");
		trackers.getAll().forEach(eventBus::register);
		eventBus.register(configEventBridge);
		listeners.setOnOpenListener(() ->
		{
			socket.send(new Payload("hello", "protocolVersion", ClanSocketConstants.PROTOCOL_VERSION, "token", null));
			clientThread.invokeLater(trackers::broadcastResetForReconnect);
		});
		listeners.setOnReidentifyListener(() -> clientThread.invokeLater(trackers::broadcastResetForReconnect));
		panelLifecycle.install();
		chatEmitter.pluginEnabled();
		final String url = CSConfigResolver.serverWsUrl(config);
		log.info("ClanSocket WS attempting connection to: '{}'", url);
		socket.tryConnect(url);
	}

	@Override
	protected void shutDown()
	{
		chatEmitter.pluginDisabled();
		trackers.getAll().forEach(eventBus::unregister);
		eventBus.unregister(configEventBridge);
		socket.disconnect();
		listeners.setOnOpenListener(null);
		panelLifecycle.shutdown();
		log.info("ClanSocket stopped");
	}

	@Subscribe
	public void onGameStateChanged(final GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			socket.kickReconnect();
		}
	}

	@Provides
	ClanSocketConfig provideConfig(final ConfigManager mgr)
	{
		return mgr.getConfig(ClanSocketConfig.class);
	}
}

package com.clansocket.panel.sections;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import com.clansocket.ClanSocketConfig;
import com.clansocket.ClanSocketConstants;
import com.clansocket.panel.PanelConstants;
import com.clansocket.panel.PanelStats;
import com.clansocket.panel.RateBuffer;
import com.clansocket.panel.widgets.StreamGate;
import com.clansocket.panel.widgets.TelemetryCard;

@Singleton
public class BodyPanel extends JPanel
{
	private final ConfigManager configManager;
	private final List<StreamGate> ordered = buildOrder();
	private final TelemetryCard[] cards = new TelemetryCard[StreamGate.ALL.size()];
	private final int[] rateScratch = new int[RateBuffer.WINDOW_SECONDS];

	@Inject
	public BodyPanel(final ConfigManager configManager, final SpriteManager spriteManager) {
		this.configManager = configManager;
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new BorderLayout());
		final JPanel grid = new JPanel(new GridLayout(0, 1, 0, PanelConstants.CARD_GRID_GAP));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		grid.setBorder(new EmptyBorder(PanelConstants.CARD_GRID_PADDING, PanelConstants.CARD_GRID_PADDING,
		        PanelConstants.CARD_GRID_PADDING, PanelConstants.CARD_GRID_PADDING));
		for (final StreamGate gate : ordered)
		{
			final TelemetryCard card = makeCard(gate);
			cards[gate.ordinal()] = card;
			spriteManager.getSpriteAsync(gate.spriteId(), 0, card::setIconImage);
			grid.add(card);
		}
		add(grid, BorderLayout.NORTH);
		alignSparkColumns();
	}

	public void refresh(final PanelStats stats, final ClanSocketConfig config)
	{
		final boolean clanMode = config.mode() == ClanSocketConfig.ConfigMode.CLAN;
		for (final StreamGate gate : ordered)
		{
			final TelemetryCard card = cards[gate.ordinal()];
			card.setActive(gate.isEnabled(config));
			card.setLocked(clanMode);
			if (BodyPanelConstants.COMPACT.contains(gate))
			{
				card.updateInfrequent(stats.count(gate), stats.lastEventAt(gate));
			} else
			{
				stats.fillRateSnapshot(gate, rateScratch);
				card.updateFrequent(stats.count(gate), rateScratch);
			}
		}
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	private void alignSparkColumns()
	{
		final FontMetrics fm = getFontMetrics(FontManager.getRunescapeSmallFont());
		final List<TelemetryCard> spark = new ArrayList<>();
		int width = 0;
		for (final StreamGate gate : ordered)
		{
			if (BodyPanelConstants.COMPACT.contains(gate))
			{
				continue;
			}
			width = Math.max(width, fm.stringWidth(gate.displayName()));
			spark.add(cards[gate.ordinal()]);
		}
		final int target = width + PanelConstants.CARD_LABEL_PAD;
		for (final TelemetryCard card : spark)
		{
			card.setLabelWidth(target);
		}
	}

	private TelemetryCard makeCard(final StreamGate gate)
	{
		final TelemetryCard.Mode mode = BodyPanelConstants.COMPACT.contains(gate)
		        ? TelemetryCard.Mode.INFREQUENT
		        : TelemetryCard.Mode.FREQUENT;
		return new TelemetryCard(gate.displayName(), mode, enabled -> configManager
		        .setConfiguration(ClanSocketConstants.CONFIG_GROUP, gate.configKey(), Boolean.toString(enabled)));
	}

	private static List<StreamGate> buildOrder()
	{
		return StreamGate.ALL.stream().filter(g -> !BodyPanelConstants.HIDDEN.contains(g))
		        .sorted(Comparator.comparing(BodyPanelConstants.COMPACT::contains)).collect(Collectors.toList());
	}
}

package com.clansocket.panel.sections;

import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;

import com.clansocket.ClanSocketConstants;
import com.clansocket.panel.PanelConstants;
import com.clansocket.panel.PanelStats;
import com.clansocket.panel.swingfactory.SwingFactory;
import com.clansocket.panel.widgets.ResetButton;
import com.clansocket.panel.widgets.StatusDot;
import com.clansocket.util.Strings;
import com.clansocket.util.Urls;

final class HeaderWidgets
{
	private HeaderWidgets() {
	}

	static void applyConnectionState(final StatusDot dot, final JLabel connStatus,
	        final PanelStats.ConnectionState state)
	{
		dot.setColor(SwingFactory.colorFor(state));
		if (state == PanelStats.ConnectionState.CONNECTED)
		{
			connStatus.setText(PanelConstants.CONN_STATUS_ONLINE);
			connStatus.setForeground(PanelConstants.COLOR_AUTH_VALID);
			return;
		}
		if (state == PanelStats.ConnectionState.CONNECTING || state == PanelStats.ConnectionState.RECONNECTING)
		{
			connStatus.setText(PanelConstants.CONN_STATUS_RECONNECT);
			connStatus.setForeground(PanelConstants.COLOR_STATE_WARN);
			return;
		}
		connStatus.setText(PanelConstants.CONN_STATUS_OFFLINE);
		connStatus.setForeground(PanelConstants.COLOR_AUTH_NOT_SET);
	}

	static void applyClanStatus(final JLabel label, final String clanName, final String reason)
	{
		if (clanName == null)
		{
			label.setText(PanelConstants.CLAN_STATUS_NONE);
			label.setForeground(PanelConstants.COLOR_AUTH_NOT_SET);
			return;
		}
		if (ClanSocketConstants.REASON_NOT_REGISTERED.equals(reason))
		{
			label.setText(String.format(PanelConstants.CLAN_STATUS_UNCLAIMED_FMT, clanName));
			label.setForeground(PanelConstants.COLOR_STATE_WARN);
			return;
		}
		if (ClanSocketConstants.REASON_NOT_MEMBER.equals(reason))
		{
			label.setText(String.format(PanelConstants.CLAN_STATUS_UNVERIFIED_FMT, clanName));
			label.setForeground(PanelConstants.COLOR_STATE_WARN);
			return;
		}
		label.setText(String.format(PanelConstants.CLAN_STATUS_FMT, clanName));
		label.setForeground(PanelConstants.COLOR_AUTH_VALID);
	}

	static JPanel buildEastBlock(final StatusDot dot, final JLabel connStatus, final Runnable resetAction)
	{
		SwingFactory.applySmall(connStatus, PanelConstants.COLOR_AUTH_NOT_SET);
		final JPanel top = new JPanel();
		top.setOpaque(false);
		top.setLayout(new BoxLayout(top, BoxLayout.X_AXIS));
		top.add(dot);
		top.add(Box.createHorizontalStrut(PanelConstants.RESET_BUTTON_RIGHT_GAP));
		top.add(connStatus);
		final JPanel bottom = new JPanel();
		bottom.setOpaque(false);
		bottom.setLayout(new BoxLayout(bottom, BoxLayout.X_AXIS));
		bottom.add(Box.createHorizontalGlue());
		bottom.add(new ResetButton(PanelConstants.RESET_LABEL, PanelConstants.RESET_TOOLTIP, resetAction));
		final JPanel block = new JPanel();
		block.setOpaque(false);
		block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));
		block.add(top);
		block.add(Box.createVerticalGlue());
		block.add(bottom);
		return block;
	}

	static String formatSubtitle(final PanelStats stats)
	{
		final String url = stats.getEndpoint();
		if (Strings.isEmpty(url))
		{
			return PanelConstants.SUBTITLE_DISCONNECTED;
		}
		return Urls.host(url);
	}
}

package com.clansocket.panel.sections;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.Objects;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ImageUtil;

import com.clansocket.panel.PanelConstants;
import com.clansocket.panel.PanelStats;
import com.clansocket.panel.swingfactory.SwingFactory;
import com.clansocket.panel.widgets.StatusDot;
import com.clansocket.tracking.identity.ClanResolver;
import com.clansocket.util.Strings;

@Singleton
public class HeaderPanel extends JPanel
{
	private final StatusDot dot = new StatusDot(PanelConstants.HEADER_DOT_DIAMETER);
	private final JLabel subtitle = new JLabel(PanelConstants.SUBTITLE_DISCONNECTED);
	private final JLabel clanStatus = new JLabel(PanelConstants.CLAN_STATUS_NONE);
	private final JLabel connStatus = new JLabel(PanelConstants.CONN_STATUS_OFFLINE);
	private final PanelStats panelStats;
	private final ClanResolver clanResolver;
	private final Client client;
	private PanelStats.ConnectionState lastState;
	private String lastSubtitleText = PanelConstants.SUBTITLE_DISCONNECTED;
	private String lastClanKey;

	@Inject
	public HeaderPanel(final PanelStats panelStats, final ClanResolver clanResolver, final Client client) {
		this.panelStats = panelStats;
		this.clanResolver = clanResolver;
		this.client = client;
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setLayout(new BorderLayout(PanelConstants.ICON_GAP, 0));
		setBorder(new CompoundBorder(
		        new MatteBorder(0, 0, PanelConstants.SEPARATOR_HEIGHT, 0, PanelConstants.COLOR_GOLD_BORDER),
		        new EmptyBorder(PanelConstants.HEADER_PADDING_Y, PanelConstants.HEADER_PADDING_X,
		                PanelConstants.HEADER_PADDING_Y, PanelConstants.HEADER_PADDING_X)));

		final BufferedImage icon = ImageUtil.loadImageResource(PanelConstants.class, PanelConstants.ICON_RESOURCE);
		final JLabel iconLabel = new JLabel(new ImageIcon(icon));
		iconLabel.setBorder(BorderFactory.createEmptyBorder());

		add(iconLabel, BorderLayout.WEST);
		add(buildTitleBlock(), BorderLayout.CENTER);
		add(HeaderWidgets.buildEastBlock(dot, connStatus, this::confirmReset), BorderLayout.EAST);
	}

	public void refresh(final PanelStats stats)
	{
		final PanelStats.ConnectionState state = stats.getConnectionState();
		if (state != lastState)
		{
			lastState = state;
			HeaderWidgets.applyConnectionState(dot, connStatus, state);
		}
		final String text = HeaderWidgets.formatSubtitle(stats);
		if (!text.equals(lastSubtitleText))
		{
			lastSubtitleText = text;
			subtitle.setText(text);
		}
		refreshClanStatus(stats);
	}

	private void refreshClanStatus(final PanelStats stats)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			if (!"loggedOut".equals(lastClanKey))
			{
				lastClanKey = "loggedOut";
				clanStatus.setText(PanelConstants.CLAN_STATUS_NOT_LOGGED_IN);
				clanStatus.setForeground(PanelConstants.COLOR_AUTH_NOT_SET);
			}
			return;
		}
		final String name = clanResolver.currentClanName();
		final String normalized = Strings.isEmpty(name) ? null : name;
		final String reason = stats.getClanReason();
		final String key = "in/" + normalized + "/" + reason;
		if (Objects.equals(key, lastClanKey))
		{
			return;
		}
		lastClanKey = key;
		HeaderWidgets.applyClanStatus(clanStatus, normalized, reason);
	}

	private JPanel buildTitleBlock()
	{
		final JPanel block = new JPanel();
		block.setOpaque(false);
		block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));

		final JLabel title = new JLabel(PanelConstants.TITLE_TEXT);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(PanelConstants.COLOR_GOLD_TEXT);
		final JLabel version = SwingFactory.smallLabel(PanelConstants.VERSION_LABEL, ColorScheme.MEDIUM_GRAY_COLOR);

		SwingFactory.applySmall(subtitle, ColorScheme.MEDIUM_GRAY_COLOR);
		SwingFactory.applySmall(clanStatus, PanelConstants.COLOR_AUTH_NOT_SET);

		final JPanel titleRow = SwingFactory.transparentRow(PanelConstants.SECTION_HEADER_GAP, title, version,
		        BorderLayout.CENTER);
		titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		subtitle.setAlignmentX(Component.LEFT_ALIGNMENT);
		clanStatus.setAlignmentX(Component.LEFT_ALIGNMENT);
		block.add(titleRow);
		block.add(subtitle);
		block.add(clanStatus);
		return block;
	}

	private void confirmReset()
	{
		final int answer = JOptionPane.showConfirmDialog(this, PanelConstants.RESET_CONFIRM_MESSAGE,
		        PanelConstants.RESET_CONFIRM_TITLE, JOptionPane.YES_NO_OPTION);
		if (answer == JOptionPane.YES_OPTION)
		{
			panelStats.resetCounts();
		}
	}
}

package com.clansocket.panel.sections;

import java.awt.BorderLayout;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.LinkBrowser;

import com.clansocket.panel.PanelConstants;
import com.clansocket.panel.swingfactory.SwingFactory;

@Singleton
public class FooterPanel extends JPanel
{
	@Inject
	public FooterPanel() {
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setLayout(new BorderLayout());
		setBorder(new CompoundBorder(
		        new MatteBorder(PanelConstants.SEPARATOR_HEIGHT, 0, 0, 0, PanelConstants.COLOR_GOLD_BORDER),
		        new EmptyBorder(PanelConstants.FOOTER_PADDING_Y, PanelConstants.FOOTER_PADDING_X,
		                PanelConstants.FOOTER_PADDING_Y, PanelConstants.FOOTER_PADDING_X)));

		add(buildLinks(), BorderLayout.WEST);
	}

	private static JPanel buildLinks()
	{
		final JPanel links = new JPanel();
		links.setOpaque(false);
		links.setLayout(new BoxLayout(links, BoxLayout.Y_AXIS));
		links.add(linkLabel(PanelConstants.FOOTER_WEB_LABEL, PanelConstants.FOOTER_WEB_URL));
		links.add(Box.createVerticalStrut(PanelConstants.FOOTER_LINK_GAP));
		links.add(linkLabel(PanelConstants.FOOTER_GITHUB_LABEL, PanelConstants.FOOTER_GITHUB_URL));
		return links;
	}

	private static JLabel linkLabel(final String text, final String url)
	{
		final JLabel label = SwingFactory.smallLabel(text, SwingConstants.LEFT, ColorScheme.LIGHT_GRAY_COLOR);
		SwingFactory.onHoverColorSwap(label, PanelConstants.COLOR_GOLD_TEXT, ColorScheme.LIGHT_GRAY_COLOR,
		        () -> LinkBrowser.browse(url));
		return label;
	}
}

package com.clansocket.panel.sections;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.ActionListener;
import java.awt.event.MouseEvent;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;

import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

import com.clansocket.panel.PanelConstants;
import com.clansocket.panel.swingfactory.SwingFactory;
import com.clansocket.panel.widgets.CollapsibleSection;

final class PresetSectionWidgets
{
	private PresetSectionWidgets() {
	}

	static CollapsibleSection makeSection(final SpriteManager spriteManager)
	{
		final CollapsibleSection s = new CollapsibleSection("Presets", null);
		spriteManager.getSpriteAsync(SpriteID.SideIcons.MUSIC, 0, s::setIconImage);
		return s;
	}

	static JPanel makeRow(final JButton... btns)
	{
		return paddedWrap(oneRowGrid(PanelConstants.PRESETS_BUTTON_GAP, btns));
	}

	static JButton button(final String label, final ActionListener action)
	{
		final JButton b = SwingFactory.applySmall(new JButton(label), null);
		b.addActionListener(action);
		return b;
	}

	static void applyModeActive(final JButton btn)
	{
		btn.setBackground(PanelConstants.COLOR_GOLD_FILL);
		btn.setForeground(Color.BLACK);
	}

	static void applyModeInactive(final JButton btn)
	{
		btn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		btn.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
	}

	static JLabel slotButton(final int slot, final Consumer<MouseEvent> onClick)
	{
		final JLabel btn = SwingFactory.applySmall(new JLabel(Integer.toString(slot), SwingConstants.CENTER), null);
		btn.setOpaque(true);
		btn.setBorder(BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_HOVER_COLOR, 1));
		btn.setPreferredSize(new Dimension(0, PanelConstants.SLOT_BUTTON_HEIGHT));
		btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		SwingFactory.onMousePressed(btn, onClick);
		applyEmpty(btn);
		return btn;
	}

	static void applyEmpty(final JLabel btn)
	{
		SwingFactory.applyColors(btn, ColorScheme.DARKER_GRAY_COLOR, ColorScheme.MEDIUM_GRAY_COLOR);
	}

	static void applySaved(final JLabel btn)
	{
		SwingFactory.applyColors(btn, ColorScheme.DARK_GRAY_HOVER_COLOR, ColorScheme.LIGHT_GRAY_COLOR);
	}

	static void applyActive(final JLabel btn)
	{
		SwingFactory.applyColors(btn, PanelConstants.COLOR_GOLD_FILL, Color.BLACK);
	}

	static JPanel makeSlotRow(final JButton saveBtn, final BiConsumer<Integer, Boolean> onClick, final JLabel... slots)
	{
		initSlotButtons(onClick, slots);
		final JPanel row = new JPanel(new BorderLayout(PanelConstants.PRESET_NUM_BUTTON_GAP, 0));
		row.setOpaque(false);
		row.add(saveBtn, BorderLayout.WEST);
		row.add(oneRowGrid(PanelConstants.PRESET_NUM_BUTTON_GAP, slots), BorderLayout.CENTER);
		return paddedWrap(row);
	}

	private static void initSlotButtons(final BiConsumer<Integer, Boolean> onClick, final JLabel... slots)
	{
		for (int i = 0; i < slots.length; i++)
		{
			final int slot = i + 1;
			slots[i] = slotButton(slot, e -> onClick.accept(slot, e.isShiftDown()));
		}
	}

	private static JPanel oneRowGrid(final int gap, final JComponent... items)
	{
		final JPanel grid = new JPanel(new GridLayout(1, items.length, gap, 0));
		grid.setOpaque(false);
		for (final JComponent item : items)
		{
			grid.add(item);
		}
		return grid;
	}

	private static JPanel paddedWrap(final JComponent content)
	{
		final JPanel wrap = new JPanel(new BorderLayout());
		wrap.setOpaque(false);
		wrap.setBorder(new EmptyBorder(PanelConstants.ROW_PADDING_Y, PanelConstants.ROW_PADDING_X,
		        PanelConstants.ROW_PADDING_Y, PanelConstants.ROW_PADDING_X));
		wrap.add(content, BorderLayout.NORTH);
		return wrap;
	}
}

package com.clansocket.panel.sections;

import java.util.Set;

import com.clansocket.panel.widgets.StreamGate;

public final class BodyPanelConstants
{
	public static final Set<StreamGate> COMPACT = Set.of(StreamGate.SKILLS_SNAPSHOT, StreamGate.LEVEL_UPS,
	        StreamGate.DEATH, StreamGate.BANK, StreamGate.PET_DROPS, StreamGate.QUESTS, StreamGate.DIARIES,
	        StreamGate.CLUES, StreamGate.COLLECTION_LOG, StreamGate.COMBAT_ACHIEVEMENTS, StreamGate.FARMING);

	public static final Set<StreamGate> HIDDEN = Set.of(StreamGate.SKILLS_SNAPSHOT);

	private BodyPanelConstants() {
	}
}

