package com.clansocket.panel.verify;

import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;

import net.runelite.client.config.ConfigManager;

import com.clansocket.ClanSocketConfig;
import com.clansocket.ClanSocketConstants;
import com.clansocket.config.preset.PresetApplier;
import com.clansocket.panel.ClanSocketPanel;

import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public final class ConsentRouter
{
	@Inject
	private ConfigManager configMgr;
	@Inject
	private Provider<ClanSocketPanel> panelProvider;
	@Inject
	private PresetApplier presetApplier;

	public void maybePrompt(final String key, final String newValue)
	{
		final String[] copy = Boolean.parseBoolean(newValue) ? ClanSocketConstants.CONSENT_COPY.get(key) : null;
		if (copy == null)
		{
			return;
		}
		ConsentDialog.confirm(panelProvider.get(), copy[0], copy[1], accepted ->
		{
			if (!accepted)
			{
				log.info("ClanSocket consent declined for {}, reverting to off", key);
				configMgr.setConfiguration(ClanSocketConstants.CONFIG_GROUP, key, false);
			}
		});
	}

	public void promptClanModeSwitch(final Runnable onAccept)
	{
		final String[] copy = ClanSocketConstants.CONSENT_COPY.get(ClanSocketConstants.CONFIG_KEY_MODE);
		ConsentDialog.confirm(panelProvider.get(), copy[0], copy[1], accepted ->
		{
			if (accepted)
			{
				presetApplier.seedClanCanonicalFromCurrent();
				onAccept.run();
				return;
			}
			log.info("ClanSocket consent declined for clan mode, reverting to manual");
			configMgr.setConfiguration(ClanSocketConstants.CONFIG_GROUP, ClanSocketConstants.CONFIG_KEY_MODE,
			        ClanSocketConfig.ConfigMode.MANUAL);
		});
	}
}

package com.clansocket.panel.verify;

import java.awt.Dimension;
import java.util.Optional;

import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;

import com.clansocket.ClanSocket;
import com.clansocket.ClanSocketConstants;
import com.clansocket.protocol.common.Payload;
import com.clansocket.protocol.system.ConsentClanProof;
import com.clansocket.transport.consent.AbstractConsentRequestStore;
import com.clansocket.transport.consent.ConsentRequestView;

abstract class AbstractConsentBanner extends JPanel
{
	private final ClanSocket socket;
	private final AbstractConsentRequestStore<?> source;
	private final ConsentBannerLayout layout;
	private float pulsePhase;

	protected AbstractConsentBanner(final ClanSocket socket, final String titleText,
	        final AbstractConsentRequestStore<?> source) {
		this.socket = socket;
		this.source = source;
		this.layout = new ConsentBannerLayout(this, titleText,
		        e -> respond(ClanSocketConstants.CONSENT_ACTION_CONFIRM, false),
		        e -> respond(ClanSocketConstants.CONSENT_ACTION_REJECT, true));
		source.addListener(() -> SwingUtilities.invokeLater(this::refresh));
		new Timer(VerifyConstants.PULSE_INTERVAL_MS, e -> tick()).start();
		refresh();
	}

	protected abstract String subtitleFormat();
	protected abstract String rejectConfirmMessage();
	protected abstract String responseFrameType();

	protected Optional<Payload> rosterForConfirm()
	{
		return Optional.empty();
	}

	protected Optional<Payload> titlesForConfirm()
	{
		return Optional.empty();
	}

	private void refresh()
	{
		final ConsentRequestView view = source.current();
		setVisible(view != null);
		if (view != null)
		{
			layout.applySubtitle(String.format(subtitleFormat(), VerifyConstants.SUBTITLE_WIDTH,
			        view.getRequestingDisplayName(), view.getRequestedRsn(), view.getRequestedClanName()));
			layout.applyCountdown(view.getExpiresAtMs() - System.currentTimeMillis());
		}
		revalidate();
		repaint();
	}

	private void respond(final String action, final boolean needConfirm)
	{
		if (needConfirm && JOptionPane.showConfirmDialog(this, rejectConfirmMessage(),
		        VerifyConstants.REJECT_CONFIRM_TITLE, JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION)
		{
			return;
		}
		final ConsentRequestView view = source.current();
		if (view == null)
		{
			return;
		}
		final boolean confirmed = ClanSocketConstants.CONSENT_ACTION_CONFIRM.equals(action);
		final ConsentClanProof proof = confirmed
		        ? new ConsentClanProof(rosterForConfirm().orElse(null), titlesForConfirm().orElse(null))
		        : null;
		socket.send(new Payload(responseFrameType(), "requestId", view.getRequestId(), "action", action, "clanProof",
		        proof));
		source.clear();
	}

	private void tick()
	{
		if (!isVisible())
		{
			return;
		}
		pulsePhase = (pulsePhase + VerifyConstants.PULSE_STEP) % 1f;
		layout.applyPulse(VerifyConstants.pulseColor(pulsePhase));
		final ConsentRequestView view = source.current();
		if (view != null)
		{
			layout.applyCountdown(view.getExpiresAtMs() - System.currentTimeMillis());
		}
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

package com.clansocket.panel;

import java.awt.Color;

import net.runelite.client.ui.ColorScheme;

public final class TelemetryFormat
{
	private TelemetryFormat() {
	}

	public static String formatAgo(final long lastEventAtMs)
	{
		if (lastEventAtMs <= PanelConstants.NEVER_EVENT_AT_MS)
		{
			return PanelConstants.AGO_NEVER;
		}
		final long agoMs = System.currentTimeMillis() - lastEventAtMs;
		final long seconds = agoMs / PanelConstants.MS_PER_SECOND;
		if (seconds < PanelConstants.SECONDS_PER_MINUTE)
		{
			return seconds + "s ago";
		}
		final long minutes = seconds / PanelConstants.SECONDS_PER_MINUTE;
		if (minutes < PanelConstants.MINUTES_PER_HOUR)
		{
			return minutes + "m ago";
		}
		final long hours = minutes / PanelConstants.MINUTES_PER_HOUR;
		if (hours < PanelConstants.HOURS_PER_DAY)
		{
			return hours + "h ago";
		}
		return (hours / PanelConstants.HOURS_PER_DAY) + "d ago";
	}

	public static Color dotColor(final long lastEventAtMs)
	{
		if (lastEventAtMs <= PanelConstants.NEVER_EVENT_AT_MS)
		{
			return ColorScheme.MEDIUM_GRAY_COLOR;
		}
		final long agoMs = System.currentTimeMillis() - lastEventAtMs;
		return agoMs <= PanelConstants.RECENT_THRESHOLD_MS
		        ? ColorScheme.PROGRESS_COMPLETE_COLOR
		        : ColorScheme.MEDIUM_GRAY_COLOR;
	}
}

package com.clansocket.panel;

import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;

import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import com.clansocket.ClanSocketConfig;

@Singleton
public class PanelLifecycle
{
	private final ClientToolbar clientToolbar;
	private final Provider<ClanSocketPanel> panelProvider;
	private final PanelStats panelStats;
	private final ClanSocketConfig config;
	private final ScheduledExecutorService executor;

	private ClanSocketPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> refreshTask;
	private ScheduledFuture<?> flushTask;

	@Inject
	public PanelLifecycle(final ClientToolbar clientToolbar, final Provider<ClanSocketPanel> panelProvider,
	        final PanelStats panelStats, final ClanSocketConfig config, final ScheduledExecutorService executor) {
		this.clientToolbar = clientToolbar;
		this.panelProvider = panelProvider;
		this.panelStats = panelStats;
		this.config = config;
		this.executor = executor;
	}

	public void install()
	{
		panelStats.loadCounts();
		panel = panelProvider.get();
		final BufferedImage icon = ImageUtil.loadImageResource(ClanSocketPanel.class, PanelConstants.ICON_RESOURCE);
		navButton = NavigationButton.builder().tooltip(PanelConstants.NAV_TOOLTIP).icon(icon)
		        .priority(PanelConstants.NAV_PRIORITY).panel(panel).build();
		clientToolbar.addNavigation(navButton);
		refreshTask = executor.scheduleAtFixedRate(this::refresh, 0, PanelConstants.REFRESH_INTERVAL_MS,
		        TimeUnit.MILLISECONDS);
		flushTask = executor.scheduleAtFixedRate(panelStats::flushCounts, PanelConstants.COUNT_FLUSH_INTERVAL_MS,
		        PanelConstants.COUNT_FLUSH_INTERVAL_MS, TimeUnit.MILLISECONDS);
	}

	public void shutdown()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(false);
			refreshTask = null;
		}
		if (flushTask != null)
		{
			flushTask.cancel(false);
			flushTask = null;
		}
		panelStats.flushCounts();
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
	}

	private void refresh()
	{
		final ClanSocketPanel current = panel;
		if (current == null)
		{
			return;
		}
		SwingUtilities.invokeLater(() -> current.refresh(panelStats, config));
	}
}

package com.clansocket.panel;

import java.util.Arrays;

public final class RateBuffer
{
	public static final int WINDOW_SECONDS = 60;

	private final Object lock = new Object();
	private final int[] buckets = new int[WINDOW_SECONDS];
	private long lastSecond = PanelConstants.UNINITIALIZED_SECOND;
	private long lastEventAtMs;

	public void bump()
	{
		synchronized (lock)
		{
			final long now = nowSeconds();
			advance(now);
			buckets[(int) (now % WINDOW_SECONDS)]++;
			lastEventAtMs = System.currentTimeMillis();
		}
	}

	public long lastEventAt()
	{
		synchronized (lock)
		{
			return lastEventAtMs;
		}
	}

	public void setLastEventAt(final long ms)
	{
		synchronized (lock)
		{
			lastEventAtMs = ms;
		}
	}

	public int[] snapshot()
	{
		final int[] out = new int[WINDOW_SECONDS];
		fillSnapshot(out);
		return out;
	}

	public void fillSnapshot(final int[] out)
	{
		synchronized (lock)
		{
			final long now = nowSeconds();
			advance(now);
			final int oldest = (int) ((now + 1) % WINDOW_SECONDS);
			for (int i = 0; i < WINDOW_SECONDS; i++)
			{
				out[i] = buckets[(oldest + i) % WINDOW_SECONDS];
			}
		}
	}

	private void advance(final long now)
	{
		if (lastSecond == PanelConstants.UNINITIALIZED_SECOND)
		{
			lastSecond = now;
			return;
		}
		final long elapsed = now - lastSecond;
		if (elapsed <= 0L)
		{
			return;
		}
		if (elapsed >= WINDOW_SECONDS)
		{
			Arrays.fill(buckets, 0);
		} else
		{
			for (long s = lastSecond + 1L; s <= now; s++)
			{
				buckets[(int) (s % WINDOW_SECONDS)] = 0;
			}
		}
		lastSecond = now;
	}

	private static long nowSeconds()
	{
		return System.currentTimeMillis() / PanelConstants.MS_PER_SECOND;
	}
}

