import com.clansocket.ClanSocketConfig;
import com.clansocket.panel.sections.BodyPanel;
import com.clansocket.panel.sections.FooterPanel;
import com.clansocket.panel.sections.HeaderPanel;
import com.clansocket.panel.sections.PresetsSection;
import com.clansocket.panel.verify.ClaimConsentBanner;
import com.clansocket.panel.verify.RsnVerifyBanner;

@Singleton
public class ClanSocketPanel extends PluginPanel
{
	private final HeaderPanel header;
	private final BodyPanel body;
	private final PresetsSection presets;
	private final RsnVerifyBanner rsnVerifyBanner;
	private final ClaimConsentBanner claimConsentBanner;

	@Inject
	public ClanSocketPanel(final HeaderPanel header, final BodyPanel body, final FooterPanel footer,
	        final PresetsSection presets, final RsnVerifyBanner rsnVerifyBanner,
	        final ClaimConsentBanner claimConsentBanner) {
		super(false);
		this.header = header;
		this.body = body;
		this.presets = presets;
		this.rsnVerifyBanner = rsnVerifyBanner;
		this.claimConsentBanner = claimConsentBanner;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		presets.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(buildTop(), BorderLayout.NORTH);
		add(makeScroll(), BorderLayout.CENTER);
		add(footer, BorderLayout.SOUTH);
	}

	private JPanel buildTop()
	{
		final JPanel top = new JPanel();
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		rsnVerifyBanner.setAlignmentX(Component.LEFT_ALIGNMENT);
		claimConsentBanner.setAlignmentX(Component.LEFT_ALIGNMENT);
		top.add(header);
		top.add(rsnVerifyBanner);
		top.add(claimConsentBanner);
		return top;
	}

	public void refresh(final PanelStats stats, final ClanSocketConfig config)
	{
		header.refresh(stats);
		body.refresh(stats, config);
		presets.refresh();
	}

	private JScrollPane makeScroll()
	{
		final JPanel contents = new JPanel()
		{
			@Override
			public Dimension getPreferredSize()
			{
				return new Dimension(PluginPanel.PANEL_WIDTH, super.getPreferredSize().height);
			}
		};
		contents.setLayout(new BoxLayout(contents, BoxLayout.Y_AXIS));
		contents.setBackground(ColorScheme.DARK_GRAY_COLOR);
		contents.add(presets);
		contents.add(body);
		final JScrollPane scroll = new JScrollPane(contents);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		return scroll;
	}
}

package com.clansocket.panel;

import java.util.concurrent.atomic.AtomicLong;

import net.runelite.client.config.ConfigManager;

import com.clansocket.ClanSocketConstants;
import com.clansocket.panel.widgets.StreamGate;

public final class PanelStatsPersistence
{
	private PanelStatsPersistence() {
	}

	public static void load(final ConfigManager mgr, final AtomicLong[] counts, final RateBuffer[] rates)
	{
		for (int i = 0; i < StreamGate.ALL.size(); i++)
		{
			final StreamGate gate = StreamGate.ALL.get(i);
			final Long c = mgr.getRSProfileConfiguration(ClanSocketConstants.CONFIG_GROUP, countConfigKey(gate),
			        long.class);
			counts[i].set(c == null ? 0L : c);
			final Long t = mgr.getRSProfileConfiguration(ClanSocketConstants.CONFIG_GROUP, lastEventAtConfigKey(gate),
			        long.class);
			rates[i].setLastEventAt(t == null ? 0L : t);
		}
	}

	public static void flush(final ConfigManager mgr, final AtomicLong[] counts, final RateBuffer[] rates)
	{
		if (mgr.getRSProfileKey() == null)
		{
			return;
		}
		for (int i = 0; i < StreamGate.ALL.size(); i++)
		{
			final StreamGate gate = StreamGate.ALL.get(i);
			mgr.setRSProfileConfiguration(ClanSocketConstants.CONFIG_GROUP, countConfigKey(gate), counts[i].get());
			mgr.setRSProfileConfiguration(ClanSocketConstants.CONFIG_GROUP, lastEventAtConfigKey(gate),
			        rates[i].lastEventAt());
		}
	}

	public static void reset(final ConfigManager mgr, final AtomicLong[] counts, final RateBuffer[] rates)
	{
		for (int i = 0; i < counts.length; i++)
		{
			counts[i].set(0L);
			rates[i].setLastEventAt(0L);
		}
		if (mgr.getRSProfileKey() == null)
		{
			return;
		}
		for (final StreamGate gate : StreamGate.ALL)
		{
			mgr.unsetRSProfileConfiguration(ClanSocketConstants.CONFIG_GROUP, countConfigKey(gate));
			mgr.unsetRSProfileConfiguration(ClanSocketConstants.CONFIG_GROUP, lastEventAtConfigKey(gate));
		}
	}

	private static String countConfigKey(final StreamGate gate)
	{
		return "count." + normalizeKey(gate.displayName());
	}

	private static String lastEventAtConfigKey(final StreamGate gate)
	{
		return "lastat." + normalizeKey(gate.displayName());
	}

	private static String normalizeKey(final String displayName)
	{
		return displayName.toLowerCase().replace(' ', '_').replace('-', '_');
	}
}

package com.clansocket.panel.swingfactory;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Map;
import java.util.function.Consumer;

import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import com.clansocket.panel.PanelStats;

public final class SwingFactory
{
	private static final Map<PanelStats.ConnectionState, Color> CONNECTION_COLORS = Map.of(
	        PanelStats.ConnectionState.CONNECTED, ColorScheme.PROGRESS_COMPLETE_COLOR,
	        PanelStats.ConnectionState.CONNECTING, ColorScheme.PROGRESS_INPROGRESS_COLOR,
	        PanelStats.ConnectionState.RECONNECTING, ColorScheme.PROGRESS_INPROGRESS_COLOR);

	private SwingFactory() {
	}

	public static JLabel smallLabel(final String text, final Color color)
	{
		return smallLabel(text, SwingConstants.LEADING, color);
	}

	public static JLabel smallLabel(final String text, final int alignment, final Color color)
	{
		final JLabel l = new JLabel(text, alignment);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		return l;
	}

	public static <T extends JComponent> T applySmall(final T component, final Color fg)
	{
		component.setFont(FontManager.getRunescapeSmallFont());
		if (fg != null)
		{
			component.setForeground(fg);
		}
		return component;
	}

	public static <T extends JComponent> T applyColors(final T component, final Color bg, final Color fg)
	{
		component.setBackground(bg);
		component.setForeground(fg);
		return component;
	}

	public static Color colorFor(final PanelStats.ConnectionState state)
	{
		return CONNECTION_COLORS.getOrDefault(state, ColorScheme.PROGRESS_ERROR_COLOR);
	}

	public static JPanel transparentRow(final int hgap, final Component leading, final Component fill,
	        final String fillSide)
	{
		final JPanel row = new JPanel(new BorderLayout(hgap, 0));
		row.setOpaque(false);
		row.add(leading, BorderLayout.WEST);
		row.add(fill, fillSide);
		return row;
	}

	public static void onHoverColorSwap(final Component c, final Color hoverFg, final Color restingFg,
	        final Runnable onClick)
	{
		c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		c.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(final MouseEvent e)
			{
				onClick.run();
			}

			@Override
			public void mouseEntered(final MouseEvent e)
			{
				c.setForeground(hoverFg);
			}

			@Override
			public void mouseExited(final MouseEvent e)
			{
				c.setForeground(restingFg);
			}
		});
	}

	public static void onMousePressed(final Component c, final Consumer<MouseEvent> action)
	{
		c.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(final MouseEvent e)
			{
				action.accept(e);
			}
		});
	}
}

package com.clansocket.panel;

import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.client.config.ConfigManager;

import com.clansocket.panel.widgets.StreamGate;

@Singleton
public class PanelStats
{
	public enum ConnectionState
	{
		DISCONNECTED, CONNECTING, CONNECTED, RECONNECTING
	}

	private final ConfigManager configManager;
	private final AtomicReference<ConnectionState> connectionState = new AtomicReference<>(
	        ConnectionState.DISCONNECTED);
	private volatile String endpoint = "";
	private volatile String clanReason;
	private final AtomicLong[] counts;
	private final RateBuffer[] rates;

	@Inject
	public PanelStats(final ConfigManager configManager) {
		this.configManager = configManager;
		final int n = StreamGate.ALL.size();
		this.counts = new AtomicLong[n];
		this.rates = new RateBuffer[n];
		for (int i = 0; i < n; i++)
		{
			counts[i] = new AtomicLong();
			rates[i] = new RateBuffer();
		}
	}

	public ConnectionState getConnectionState()
	{
		return connectionState.get();
	}

	public String getEndpoint()
	{
		return endpoint;
	}

	public String getClanReason()
	{
		return clanReason;
	}

	public void setClanReason(final String reason)
	{
		this.clanReason = reason;
	}

	public long count(final StreamGate gate)
	{
		return counts[gate.ordinal()].get();
	}

	public void bump(final StreamGate gate)
	{
		final int idx = gate.ordinal();
		counts[idx].incrementAndGet();
		rates[idx].bump();
	}

	public int[] rateSnapshot(final StreamGate gate)
	{
		return rates[gate.ordinal()].snapshot();
	}

	public void fillRateSnapshot(final StreamGate gate, final int[] out)
	{
		rates[gate.ordinal()].fillSnapshot(out);
	}

	public long lastEventAt(final StreamGate gate)
	{
		return rates[gate.ordinal()].lastEventAt();
	}

	public void loadCounts()
	{
		PanelStatsPersistence.load(configManager, counts, rates);
	}

	public void flushCounts()
	{
		PanelStatsPersistence.flush(configManager, counts, rates);
	}

	public void resetCounts()
	{
		PanelStatsPersistence.reset(configManager, counts, rates);
	}

	public void markConnecting(final String target)
	{
		endpoint = target == null ? "" : target;
		connectionState.set(ConnectionState.CONNECTING);
	}

	public void markConnected()
	{
		connectionState.set(ConnectionState.CONNECTED);
	}

	public void markDisconnected()
	{
		connectionState.set(ConnectionState.DISCONNECTED);
	}

	public void markReconnectAttempt(final int attempt)
	{
		connectionState.set(attempt == 0 ? ConnectionState.RECONNECTING : ConnectionState.DISCONNECTED);
	}
}

