import javax.swing.border.EmptyBorder;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.util.ImageUtil;

import com.clansocket.panel.PanelConstants;
import com.clansocket.panel.swingfactory.SwingFactory;

public class CollapsibleSection extends JPanel
{
	private final JLabel iconLabel = new JLabel();
	private final JPanel body;
	private final JLabel chevron = new JLabel(PanelConstants.CHEVRON_EXPANDED);
	private boolean expanded = true;

	public CollapsibleSection(final String title, final String iconName) {
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		final ImageIcon icon = loadIcon(iconName);
		if (icon != null)
		{
			iconLabel.setIcon(icon);
		}
		body = new JPanel();
		body.setLayout(new DynamicGridLayout(0, 1, 0, 0));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(makeHeader(title), BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
	}

	public void addItem(final Component c)
	{
		body.add(c);
		body.revalidate();
		body.repaint();
	}

	public void removeItem(final Component c)
	{
		body.remove(c);
		body.revalidate();
		body.repaint();
	}

	public void setExpanded(final boolean value)
	{
		if (value == expanded)
		{
			return;
		}
		expanded = value;
		body.setVisible(value);
		chevron.setText(value ? PanelConstants.CHEVRON_EXPANDED : PanelConstants.CHEVRON_COLLAPSED);
		revalidate();
		repaint();
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	public void setIconImage(final BufferedImage img)
	{
		if (img == null)
		{
			return;
		}
		final int w = Math.max(1, img.getWidth() / 2);
		final int h = Math.max(1, img.getHeight() / 2);
		final Image scaled = img.getScaledInstance(w, h, Image.SCALE_SMOOTH);
		SwingUtilities.invokeLater(() ->
		{
			iconLabel.setIcon(new ImageIcon(scaled));
			iconLabel.revalidate();
			iconLabel.repaint();
		});
	}

	private JPanel makeHeader(final String title)
	{
		final JPanel header = new JPanel(new BorderLayout(PanelConstants.SECTION_HEADER_GAP, 0));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(new EmptyBorder(PanelConstants.SECTION_HEADER_PADDING_Y, PanelConstants.ROW_PADDING_X,
		        PanelConstants.SECTION_HEADER_PADDING_Y, PanelConstants.ROW_PADDING_X));
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		SwingFactory.onMousePressed(header, e -> setExpanded(!expanded));
		header.add(makeLeft(title), BorderLayout.WEST);
		SwingFactory.applySmall(chevron, ColorScheme.MEDIUM_GRAY_COLOR);
		header.add(chevron, BorderLayout.EAST);
		return header;
	}

	private JPanel makeLeft(final String title)
	{
		final JPanel left = new JPanel(new BorderLayout(PanelConstants.SECTION_HEADER_GAP, 0));
		left.setOpaque(false);
		left.add(iconLabel, BorderLayout.WEST);
		left.add(SwingFactory.smallLabel(title, PanelConstants.COLOR_GOLD_TEXT), BorderLayout.CENTER);
		return left;
	}

	private static ImageIcon loadIcon(final String name)
	{
		if (name == null)
		{
			return null;
		}
		try
		{
			final BufferedImage img = ImageUtil.loadImageResource(CollapsibleSection.class,
			        String.format(PanelConstants.SECTION_ICON_PATH_FMT, name));
			return img == null ? null : new ImageIcon(img);
		} catch (final RuntimeException ex)
		{
			return null;
		}
	}
}

package com.clansocket.bus;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocket;
import com.clansocket.panel.PanelStats;
import com.clansocket.panel.widgets.StreamGate;
import com.clansocket.protocol.common.Payload;

@Singleton
public class EventBatcher
{
	private static final Map<String, StreamGate> GATE_BY_TYPE = Map.<String, StreamGate>ofEntries(
	        Map.entry("stats", StreamGate.SKILLS_SNAPSHOT), Map.entry("xp_gained", StreamGate.XP_GAINS),
	        Map.entry("level_up", StreamGate.LEVEL_UPS), Map.entry("damage_dealt", StreamGate.COMBAT),
	        Map.entry("damage_taken", StreamGate.COMBAT), Map.entry("death", StreamGate.DEATH),
	        Map.entry("interacting", StreamGate.COMBAT), Map.entry("slayer", StreamGate.SLAYER),
	        Map.entry("vitals", StreamGate.VITALS), Map.entry("prayers", StreamGate.PRAYER),
	        Map.entry("boosts", StreamGate.BOOSTS), Map.entry("status_effect", StreamGate.STATUS_EFFECTS),
	        Map.entry("location", StreamGate.LOCATION), Map.entry("world_hop", StreamGate.LOCATION),
	        Map.entry("container", StreamGate.INVENTORY), Map.entry("container_delta", StreamGate.INVENTORY),
	        Map.entry("bank_open", StreamGate.BANK), Map.entry("bank_close", StreamGate.BANK),
	        Map.entry("rune_pouch", StreamGate.RUNE_POUCH), Map.entry("loot", StreamGate.LOOT),
	        Map.entry("pet_drop", StreamGate.PET_DROPS), Map.entry("quests", StreamGate.QUESTS),
	        Map.entry("quest_completed", StreamGate.QUESTS), Map.entry("diaries", StreamGate.DIARIES),
	        Map.entry("diary_completed", StreamGate.DIARIES), Map.entry("clue_completed", StreamGate.CLUES),
	        Map.entry("clue_opened", StreamGate.CLUES), Map.entry("collection_log_entry", StreamGate.COLLECTION_LOG),
	        Map.entry("collection_log_snapshot", StreamGate.COLLECTION_LOG),
	        Map.entry("combat_achievements_catalog", StreamGate.COMBAT_ACHIEVEMENTS),
	        Map.entry("combat_achievements_snapshot", StreamGate.COMBAT_ACHIEVEMENTS),
	        Map.entry("combat_achievement_completed", StreamGate.COMBAT_ACHIEVEMENTS),
	        Map.entry("menu_action", StreamGate.MENU_ACTIONS), Map.entry("farming_patch", StreamGate.FARMING),
	        Map.entry("chat", StreamGate.CLAN_CHAT));

	@Inject
	private ClanSocket socket;
	@Inject
	private Client client;
	@Inject
	private PanelStats panelStats;

	private final List<Payload> pending = new ArrayList<>();
	private long nextSeq = 1L;

	public void enqueue(final Payload event)
	{
		final StreamGate gate = GATE_BY_TYPE.get(event.type());
		if (gate != null)
		{
			panelStats.bump(gate);
		}
		synchronized (pending)
		{
			pending.add(event);
		}
	}

	@Subscribe(priority = -1f)
	public void onGameTick(final GameTick tick)
	{
		flush();
	}

	@Subscribe
	public void onGameStateChanged(final GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			synchronized (pending)
			{
				pending.clear();
			}
			nextSeq = 1L;
		}
	}

	private void flush()
	{
		final List<Payload> toSend;
		synchronized (pending)
		{
			if (pending.isEmpty())
			{
				return;
			}
			toSend = new ArrayList<>(pending);
			pending.clear();
		}
		socket.send(new Payload("batch", "seq", nextSeq++, "tick", client.getTickCount(), "events", toSend));
	}
}

