package com.clansocket.bus.primitive;

import java.util.Optional;

import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.bus.AbstractStateTracker;
import com.clansocket.protocol.common.Payload;

public abstract class AbstractPolledSnapshotTracker extends AbstractStateTracker
{
	private final AbstractSnapshotEmitter emitter;
	private final int warmupTickWait;
	private final int repollInterval;
	private volatile boolean armed;
	private volatile int warmupTicks;
	private volatile int repollTicks;

	protected AbstractPolledSnapshotTracker(final AbstractSnapshotEmitter emitter, final int warmupTickWait,
	        final int repollInterval) {
		this.emitter = emitter;
		this.warmupTickWait = warmupTickWait;
		this.repollInterval = repollInterval;
	}

	public final Optional<Payload> currentSnapshot()
	{
		return emitter.snapshotNow();
	}

	protected final void emitSnapshot()
	{
		emitter.emit();
	}

	@Override
	protected final void onLoginScreen()
	{
		armed = false;
		warmupTicks = 0;
		repollTicks = 0;
		emitter.clearFingerprint();
	}

	@Override
	protected final void onLoggedIn()
	{
		armed = true;
		warmupTicks = 0;
	}

	@Override
	protected final void emitFreshSnapshot()
	{
		emitter.clearFingerprint();
		armed = true;
		warmupTicks = 0;
	}

	@Subscribe
	public final void onGameTick(final GameTick tick)
	{
		if (!isLoggedIn())
		{
			return;
		}
		if (armed)
		{
			if (warmupTicks++ < warmupTickWait)
			{
				return;
			}
			emitSnapshot();
			armed = false;
			repollTicks = 0;
			return;
		}
		if (++repollTicks >= repollInterval)
		{
			repollTicks = 0;
			emitSnapshot();
		}
	}
}

package com.clansocket.bus.primitive;

import java.util.List;
import java.util.Optional;

import javax.inject.Inject;

import net.runelite.api.Client;

import org.slf4j.Logger;

import com.clansocket.bus.EventBatcher;
import com.clansocket.protocol.common.Payload;

public abstract class AbstractSnapshotEmitter
{
	@Inject
	protected Client client;
	@Inject
	protected EventBatcher batcher;

	private final String listField;
	private final String emitKind;
	private final Logger logger;
	private volatile String lastFingerprint;
	private volatile Payload lastSnapshot;

	protected AbstractSnapshotEmitter(final String listField, final String emitKind, final Logger logger) {
		this.listField = listField;
		this.emitKind = emitKind;
		this.logger = logger;
	}

	protected abstract Optional<Payload> buildSnapshot();

	public final void clearFingerprint()
	{
		lastFingerprint = null;
	}

	public final Optional<Payload> snapshotNow()
	{
		return Optional.ofNullable(lastSnapshot);
	}

	public final void emit()
	{
		try
		{
			final Optional<Payload> opt = buildSnapshot();
			if (opt.isEmpty())
			{
				return;
			}
			final Payload snapshot = opt.get();
			lastSnapshot = snapshot;
			final String fp = (String) snapshot.get("fingerprint");
			if (fp.equals(lastFingerprint))
			{
				return;
			}
			lastFingerprint = fp;
			batcher.enqueue(snapshot);
			final Object list = snapshot.get(listField);
			final int size = list instanceof List ? ((List<?>) list).size() : 0;
			logger.debug("ClanSocket {} clan={} count={} fingerprint={}", emitKind, snapshot.get("clanName"), size, fp);
		} catch (final RuntimeException t)
		{
			logger.debug("ClanSocket {} snapshot failed", emitKind, t);
		}
	}
}

