package com.clansocket.bus;

import java.util.Arrays;
import java.util.List;
import java.util.function.Function;
import java.util.function.ToIntFunction;

public final class Hashes
{
	public static final long HASH_PRIME = 31L;

	private Hashes() {
	}

	public static String of(final Object... parts)
	{
		return Integer.toHexString(Arrays.deepHashCode(parts));
	}

	public static <T> String ofMapped(final List<T> items, final Function<T, Object[]> projection)
	{
		return of(items.stream().map(projection).flatMap(Arrays::stream).toArray());
	}

	public static <T> long pairsLong(final List<T> items, final ToIntFunction<T> a, final ToIntFunction<T> b)
	{
		long h = 1L;
		for (final T item : items)
		{
			h = h * HASH_PRIME + a.applyAsInt(item);
			h = h * HASH_PRIME + b.applyAsInt(item);
		}
		return h;
	}

	public static long rollingArrays(final int seed, final int[]... arrays)
	{
		long h = seed;
		if (arrays.length == 0)
		{
			return h;
		}
		final int len = arrays[0].length;
		for (int i = 0; i < len; i++)
		{
			for (final int[] arr : arrays)
			{
				h = h * HASH_PRIME + arr[i];
			}
		}
		return h;
	}

	public static long rollingLong(final int... values)
	{
		long h = 1L;
		for (final int v : values)
		{
			h = h * HASH_PRIME + v;
		}
		return h;
	}
}

package com.clansocket.bus;

import java.util.Objects;

public final class Latched<T>
{
	private T last;
	private boolean initialized;

	public Latched() {
	}

	public Latched(final T initial) {
		this.last = initial;
		this.initialized = true;
	}

	public boolean update(final T next)
	{
		if (initialized && Objects.equals(last, next))
		{
			return false;
		}
		last = next;
		initialized = true;
		return true;
	}

	public void preset(final T value)
	{
		last = value;
		initialized = true;
	}

	public void reset()
	{
		last = null;
		initialized = false;
	}

	public T current()
	{
		return last;
	}
}

package com.clansocket.bus;

import java.util.Deque;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.concurrent.atomic.AtomicInteger;

import javax.inject.Singleton;

import com.clansocket.ClanSocketConstants;

import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public final class PendingQueue
{
	private final Deque<String> queue = new ConcurrentLinkedDeque<>();
	private final AtomicInteger size = new AtomicInteger();
	private long dropped;

	public void offer(final String json)
	{
		queue.offerLast(json);
		if (size.incrementAndGet() <= ClanSocketConstants.QUEUE_CAP)
		{
			return;
		}
		if (queue.pollFirst() != null)
		{
			size.decrementAndGet();
			noteDropped();
		}
	}

	public String poll()
	{
		final String head = queue.pollFirst();
		if (head != null)
		{
			size.decrementAndGet();
		}
		return head;
	}

	public void clear()
	{
		queue.clear();
		size.set(0);
	}

	private void noteDropped()
	{
		dropped++;
		if (dropped % ClanSocketConstants.QUEUE_DROP_LOG_INTERVAL == 0)
		{
			log.warn("ClanSocket WS pending queue at cap ({}), dropped {} events while disconnected",
			        ClanSocketConstants.QUEUE_CAP, dropped);
		}
	}
}

