	private final Gson gson;

	public SocketCallback(final ClanSocket socket, final GameChatEmitter chatEmitter, final SessionStore sessions,
	        final PanelStats panelStats, final ConsentDispatch consentDispatch, final LifecycleListeners listeners,
	        final PresetApplier presetApplier, final ClanSocketConfig config, final Gson gson) {
		this.socket = socket;
		this.chatEmitter = chatEmitter;
		this.sessions = sessions;
		this.panelStats = panelStats;
		this.consentDispatch = consentDispatch;
		this.listeners = listeners;
		this.presetApplier = presetApplier;
		this.config = config;
		this.gson = gson;
	}

	@Override
	public void onOpen(final WebSocket webSocket, final Response response)
	{
		log.info("ClanSocket WS connected to {}", socket.getEndpoint());
		socket.resetBackoff();
		chatEmitter.connected(socket.getEndpoint());
		panelStats.markConnected();
		socket.drainAndArm(webSocket);
		listeners.fireOnOpen();
	}

	@Override
	public void onMessage(final WebSocket webSocket, final String text)
	{
		log.debug("ClanSocket WS message: {}", text);
		try
		{
			final JsonObject obj = gson.fromJson(text, JsonObject.class);
			if (!obj.has(ClanSocketConstants.WS_FIELD_TYPE))
			{
				return;
			}
			dispatch(obj);
		} catch (final RuntimeException e)
		{
			log.warn("ClanSocket WS message parse failed: {}", e.getMessage());
		}
	}

	private void dispatch(final JsonObject obj)
	{
		final String type = obj.get(ClanSocketConstants.WS_FIELD_TYPE).getAsString();
		if (consentDispatch.tryHandle(type, obj))
		{
			return;
		}
		if (ClanSocketConstants.WS_TYPE_WELCOME.equals(type) && obj.has(ClanSocketConstants.WS_FIELD_SESSION_ID))
		{
			handleWelcome(obj);
		} else if (ClanSocketConstants.WS_TYPE_CLAN_REMINDER.equals(type))
		{
			handleClanReminder(obj);
		} else if (ClanSocketConstants.WS_TYPE_BROADCAST.equals(type))
		{
			chatEmitter.serverBroadcast(Json.optString(obj, ClanSocketConstants.WS_FIELD_MESSAGE));
		} else if (ClanSocketConstants.WS_TYPE_CLAN_CONFIG_PUSH.equals(type))
		{
			if (config.mode() != ClanSocketConfig.ConfigMode.CLAN)
			{
				return;
			}
			presetApplier.apply(gson.fromJson(obj.get(ClanSocketConstants.WS_FIELD_PAYLOAD), PresetSchema.class),
			        PresetApplier.Source.CLAN);
		} else
		{
			handleControlEvent(type);
		}
	}

	private void handleControlEvent(final String type)
	{
		if (ClanSocketConstants.WS_TYPE_IDENTITY_OK.equals(type))
		{
			panelStats.setClanReason(null);
		} else if (ClanSocketConstants.WS_TYPE_REIDENTIFY.equals(type))
		{
			listeners.fireOnReidentify();
		}
	}

	private void handleWelcome(final JsonObject obj)
	{
		sessions.setSessionId(obj.get(ClanSocketConstants.WS_FIELD_SESSION_ID).getAsString());
		panelStats.setClanReason(null);
	}

	private void handleClanReminder(final JsonObject obj)
	{
		final String reason = Json.optString(obj, ClanSocketConstants.WS_FIELD_REASON);
		panelStats.setClanReason(reason);
		chatEmitter.clanReminder(reason, Json.optString(obj, ClanSocketConstants.WS_FIELD_CLAN_NAME));
	}

	@Override
	public void onClosed(final WebSocket webSocket, final int code, final String reason)
	{
		log.info("ClanSocket WS closed ({}) {}", code, reason);
		sessions.clear();
		socket.handleClose(Strings.isNotEmpty(reason) ? reason : "code " + code);
	}

	@Override
	public void onFailure(final WebSocket webSocket, final Throwable t, final Response response)
	{
		log.warn("ClanSocket WS failure: {}", t.getMessage());
		sessions.clear();
		socket.handleClose(t.getMessage());
	}
}

package com.clansocket;

import java.util.concurrent.ScheduledExecutorService;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.clansocket.bus.PendingQueue;
import com.clansocket.chat.GameChatEmitter;
import com.clansocket.config.preset.PresetApplier;
import com.clansocket.panel.PanelStats;
import com.clansocket.transport.LifecycleListeners;
import com.clansocket.transport.ReconnectScheduler;
import com.clansocket.transport.SessionStore;
import com.clansocket.transport.SocketCallback;
import com.clansocket.transport.WsOpener;
import com.clansocket.transport.consent.ConsentDispatch;
import com.google.gson.Gson;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.WebSocket;

@Slf4j
@Singleton
public class ClanSocket
{
	@Inject
	private WsOpener opener;
	@Inject
	private GameChatEmitter chatEmitter;
	@Inject
	private SessionStore sessions;
	@Inject
	private PanelStats panelStats;
	@Inject
	private ReconnectScheduler reconnectScheduler;
	@Inject
	private ConsentDispatch consentDispatch;
	@Inject
	private LifecycleListeners listeners;
	@Inject
	private PresetApplier presetApplier;
	@Inject
	private PendingQueue pending;
	@Inject
	private ScheduledExecutorService executor;
	@Inject
	private ClanSocketConfig config;
	@Inject
	private Gson gson;
	@Getter
	private volatile String endpoint;
	private volatile boolean shouldBeConnected;
	private volatile boolean drained;
	private int retryAttempts;
	private WebSocket ws;

	public synchronized boolean isConnected()
	{
		return ws != null;
	}

	public synchronized void connect(final String target)
	{
		this.endpoint = target;
		this.shouldBeConnected = true;
		reconnectScheduler.reset();
		panelStats.markConnecting(target);
		openNow();
	}

	public void tryConnect(final String target)
	{
		try
		{
			connect(target);
		} catch (final IllegalArgumentException ex)
		{
			log.warn("ClanSocket WS connect rejected: {} ({})", target, ex.getMessage());
		}
	}

	public synchronized void disconnect()
	{
		shouldBeConnected = false;
		drained = false;
		reconnectScheduler.cancel();
		if (ws != null)
		{
			ws.close(ClanSocketConstants.NORMAL_CLOSURE, "disconnect");
			ws = null;
		}
		pending.clear();
		panelStats.markDisconnected();
	}

	public void send(final Object payload)
	{
		executor.execute(() -> doSend(payload));
	}

	private void doSend(final Object payload)
	{
		final String json = gson.toJson(payload);
		if (json.length() > ClanSocketConstants.PAYLOAD_WARN_BYTES)
		{
			log.warn("ClanSocket WS payload {} bytes approaching server cap; risk of server-side rejection",
			        json.length());
		}
		final WebSocket local;
		synchronized (this)
		{
			local = ws;
		}
		if (local == null || !drained)
		{
			pending.offer(json);
			return;
		}
		local.send(json);
	}

	public void drainAndArm(final WebSocket newWs)
	{
		executor.execute(() ->
		{
			String msg;
			while ((msg = pending.poll()) != null)
			{
				newWs.send(msg);
			}
			drained = true;
		});
	}

	public synchronized void resetBackoff()
	{
		reconnectScheduler.reset();
		retryAttempts = 0;
	}

	public synchronized void kickReconnect()
	{
		if (!shouldBeConnected || ws != null)
		{
			return;
		}
		reconnectScheduler.cancel();
		reconnectScheduler.reset();
		openNow();
	}

	public synchronized void handleClose(final String reason)
	{
		ws = null;
		drained = false;
		if (!shouldBeConnected)
		{
			return;
		}
		chatEmitter.disconnected(reason);
		panelStats.markReconnectAttempt(retryAttempts++);
		reconnectScheduler.schedule(this::openNow);
	}

	private synchronized void openNow()
	{
		if (!shouldBeConnected || endpoint == null)
		{
			return;
		}
		ws = opener.open(endpoint, new SocketCallback(this, chatEmitter, sessions, panelStats, consentDispatch,
		        listeners, presetApplier, config, gson));
	}
}

package com.clansocket.chat;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;

import com.clansocket.ClanSocketConstants;
import com.clansocket.util.Strings;
import com.clansocket.util.Urls;

@Singleton
public class GameChatEmitter
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ScheduledExecutorService executor;

	private ScheduledFuture<?> pendingOfflineTask;
	private boolean offlineAnnounced;
	private final Map<String, Long> reminderLastShown = new HashMap<>();

	public void pluginEnabled()
	{
		announce("Plugin active. Connecting to clan dashboard...");
	}

	public void pluginDisabled()
	{
		synchronized (this)
		{
			cancelPendingOffline();
			offlineAnnounced = false;
		}
		announce("Plugin disabled. Streaming stopped — no data leaving your client.");
	}

	public synchronized void connected(final String url)
	{
		if (cancelPendingOffline())
		{
			return;
		}
		if (!offlineAnnounced)
		{
			return;
		}
		offlineAnnounced = false;
		announce("Connection " + ClanSocketConstants.LIVE_TAG + " — telemetry streaming to " + safeHost(url) + ".");
	}

	public synchronized void disconnected(final String reason)
	{
		if (pendingOfflineTask != null || offlineAnnounced)
		{
			return;
		}
		pendingOfflineTask = executor.schedule(() -> announceOffline(reason), ClanSocketConstants.DISCONNECT_GRACE_MS,
		        TimeUnit.MILLISECONDS);
	}

	public synchronized void clanReminder(final String reason, final String clanName)
	{
		final String fmt = ClanSocketConstants.CLAN_REMINDER_MSG_BY_REASON.get(reason);
		final String key = reason + ":" + clanName;
		final long now = System.currentTimeMillis();
		if (fmt == null || Strings.isEmpty(clanName)
		        || now - reminderLastShown.getOrDefault(key, 0L) < ClanSocketConstants.CLAN_REMINDER_INTERVAL_MS)
		{
			return;
		}
		reminderLastShown.put(key, now);
		announce(String.format(fmt, clanName));
	}

	public void sessionReminder(final String actualClanName, final String actualClanRank, final boolean connected)
	{
		if (Strings.isEmpty(actualClanName))
		{
			announce(
			        "Streaming requires clan membership — you must be in an in-game clan for the dashboard to receive data.");
			return;
		}
		final String tag = connected ? ClanSocketConstants.LIVE_TAG : ClanSocketConstants.OFFLINE_TAG;
		final String suffix = connected ? ". Disable the plugin to disconnect." : ". Attempting to reconnect...";
		final String rankPart = Strings.isEmpty(actualClanRank) ? "" : " as " + actualClanRank;
		announce("Streaming to " + actualClanName + rankPart + " — status: " + tag + suffix);
	}

	public void serverBroadcast(final String message)
	{
		if (Strings.isEmpty(message))
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
		});
	}

	private synchronized void announceOffline(final String reason)
	{
		pendingOfflineTask = null;
		offlineAnnounced = true;
		final String suffix = Strings.isNotEmpty(reason) ? " (" + reason + ")" : "";
		announce("Connection " + ClanSocketConstants.OFFLINE_TAG + suffix + ". Attempting to reconnect...");
	}

	private synchronized boolean cancelPendingOffline()
	{
		if (pendingOfflineTask == null)
		{
			return false;
		}
		pendingOfflineTask.cancel(false);
		pendingOfflineTask = null;
		return true;
	}

	private void announce(final String text)
	{
		serverBroadcast(ClanSocketConstants.BRAND_PREFIX + text);
	}

	private static String safeHost(final String url)
	{
		return url == null ? "?" : Urls.host(url);
	}
}

