package com.clansocket;

import com.clansocket.util.Strings;

public final class CSConfigResolver
{
	private CSConfigResolver() {
	}

	public static String serverWsUrl(final ClanSocketConfig config)
	{
		final String raw = config.serverWsUrl();
		final String picked = Strings.isBlank(raw) ? ClanSocketConstants.SERVER_URL : raw.trim();
		final String stripped = picked.endsWith("/") ? picked.substring(0, picked.length() - 1) : picked;
		return stripped.contains(ClanSocketConstants.SCHEME_DELIM)
		        ? stripped
		        : ClanSocketConstants.SCHEME_WSS + stripped;
	}
}

package com.clansocket.config.preset;

import java.io.IOException;
import java.util.OptionalInt;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.client.config.ConfigManager;

import com.clansocket.ClanSocketConfig;
import com.clansocket.ClanSocketConstants;
import com.clansocket.util.NumberInput;

import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
public final class PresetManager
{
	private final ClanSocketConfig config;
	private final ConfigManager configManager;
	private final PresetStore store;
	private final PresetApplier applier;
	private final PresetCodec codec;

	@Inject
	public PresetManager(final ClanSocketConfig config, final ConfigManager configManager, final PresetStore store,
	        final PresetApplier applier, final PresetCodec codec) {
		this.config = config;
		this.configManager = configManager;
		this.store = store;
		this.applier = applier;
		this.codec = codec;
	}

	public boolean useSlot(final int slot)
	{
		if (slotExists(slot))
		{
			try
			{
				applySlot(slot);
			} catch (final IOException | IllegalArgumentException ex)
			{
				log.warn("ClanSocket preset: load slot {} failed: {}", slot, ex.getMessage());
				return false;
			}
		} else if (!saveToSlot(slot))
		{
			return false;
		}
		setActiveSlot(slot);
		return true;
	}

	public void applySlot(final int slot) throws IOException
	{
		store.read(slot).ifPresent(s -> applier.apply(s, PresetApplier.Source.LOCAL));
	}

	public OptionalInt saveCurrent()
	{
		if (config.mode() == ClanSocketConfig.ConfigMode.CLAN)
		{
			log.info(PresetConstants.LOG_SAVE_BLOCKED_CLAN_MODE);
			return OptionalInt.empty();
		}
		final int active = getActiveSlot();
		if (active >= 1 && active <= PresetConstants.MAX_SLOTS)
		{
			return saveToSlot(active) ? OptionalInt.of(active) : OptionalInt.empty();
		}
		return persistAsNewPreset(PresetCodec.snapshot(configManager));
	}

	public boolean saveToSlot(final int slot)
	{
		if (config.mode() == ClanSocketConfig.ConfigMode.CLAN)
		{
			log.info(PresetConstants.LOG_SAVE_BLOCKED_CLAN_MODE);
			return false;
		}
		try
		{
			store.write(slot, PresetCodec.snapshot(configManager));
			return true;
		} catch (final IOException ex)
		{
			log.warn(PresetConstants.LOG_HANDLER_FAILED, ex);
			return false;
		}
	}

	public boolean delete(final int slot)
	{
		if (!store.existsForSlot(slot))
		{
			log.info(PresetConstants.LOG_DELETE_EMPTY);
			return false;
		}
		return store.delete(slot);
	}

	public boolean slotExists(final int slot)
	{
		return store.existsForSlot(slot);
	}

	public int getActiveSlot()
	{
		return NumberInput.parseIntOr(configManager.getConfiguration(ClanSocketConstants.CONFIG_GROUP,
		        com.clansocket.panel.PanelConstants.PRESETS_ACTIVE_SLOT_KEY), -1);
	}

	public void setActiveSlot(final int slot)
	{
		configManager.setConfiguration(ClanSocketConstants.CONFIG_GROUP,
		        com.clansocket.panel.PanelConstants.PRESETS_ACTIVE_SLOT_KEY, Integer.toString(slot));
	}

	public String labelFor(final int slot)
	{
		return store.existsForSlot(slot)
		        ? String.format(PresetConstants.LABEL_PRESET_FORMAT, slot)
		        : String.format(PresetConstants.LABEL_PRESET_EMPTY_FORMAT, slot);
	}

	private OptionalInt persistAsNewPreset(final PresetSchema schema)
	{
		try
		{
			final OptionalInt match = store.findMatchingSlot(codec.canonicalHash(schema));
			if (match.isPresent())
			{
				return match;
			}
			final OptionalInt next = store.findNextEmptySlot();
			if (next.isEmpty())
			{
				log.info(PresetConstants.LOG_SLOTS_FULL);
				return OptionalInt.empty();
			}
			store.write(next.getAsInt(), schema);
			return next;
		} catch (final IOException ex)
		{
			log.warn(PresetConstants.LOG_HANDLER_FAILED, ex);
			return OptionalInt.empty();
		}
	}
}

package com.clansocket.config.preset;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Optional;
import java.util.OptionalInt;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
public final class PresetStore
{
	private final PresetCodec codec;

	@Inject
	public PresetStore(final PresetCodec codec) {
		this.codec = codec;
		ensureDir();
	}

	public boolean existsForSlot(final int slot)
	{
		return slot >= 1 && slot <= PresetConstants.MAX_SLOTS && pathFor(slot).toFile().exists();
	}

	public Optional<PresetSchema> read(final int slot) throws IOException
	{
		if (!existsForSlot(slot))
		{
			return Optional.empty();
		}
		final String json = Files.readString(pathFor(slot), StandardCharsets.UTF_8);
		return Optional.of(codec.decode(json));
	}

	public void write(final int slot, final PresetSchema schema) throws IOException
	{
		ensureDir();
		Files.writeString(pathFor(slot), codec.encode(schema), StandardCharsets.UTF_8);
	}

	public boolean delete(final int slot)
	{
		return pathFor(slot).toFile().delete();
	}

	public OptionalInt findMatchingSlot(final String targetHash)
	{
		for (int i = 1; i <= PresetConstants.MAX_SLOTS; i++)
		{
			if (!existsForSlot(i))
			{
				continue;
			}
			try
			{
				final Optional<PresetSchema> opt = read(i);
				if (opt.isPresent() && codec.canonicalHash(opt.get()).equals(targetHash))
				{
					return OptionalInt.of(i);
				}
			} catch (final IOException | IllegalArgumentException ex)
			{
				log.debug("ClanSocket preset: skipping corrupted slot {}: {}", i, ex.getMessage());
			}
		}
		return OptionalInt.empty();
	}

	public OptionalInt findNextEmptySlot()
	{
		for (int i = 1; i <= PresetConstants.MAX_SLOTS; i++)
		{
			if (!existsForSlot(i))
			{
				return OptionalInt.of(i);
			}
		}
		return OptionalInt.empty();
	}

	private static Path pathFor(final int slot)
	{
		return PresetConstants.PRESETS_DIR.toPath().resolve(String.format(PresetConstants.FILENAME_PATTERN, slot));
	}

	private static void ensureDir()
	{
		PresetConstants.PRESETS_DIR.mkdirs();
	}
}

package com.clansocket.config.preset;

import java.io.File;

import net.runelite.client.RuneLite;

public final class PresetConstants
{
	public static final String CLANSOCKET_DIR_NAME = "clansocket";
	public static final String PRESETS_DIR_NAME = "presets";
	public static final File PRESETS_DIR = new File(new File(RuneLite.RUNELITE_DIR, CLANSOCKET_DIR_NAME),
	        PRESETS_DIR_NAME);

	public static final int MAX_SLOTS = 7;

	public static final String FILENAME_PATTERN = "preset-%d.json";

	public static final int SCHEMA_VERSION = 1;

	public static final String LABEL_PRESET_FORMAT = "Preset %d";
	public static final String LABEL_PRESET_EMPTY_FORMAT = "Preset %d (empty)";

	public static final String LOG_SLOTS_FULL = "ClanSocket preset: all slots full — delete one first";
	public static final String LOG_DELETE_EMPTY = "ClanSocket preset: slot already empty";
	public static final String LOG_BAD_JSON = "ClanSocket preset: invalid JSON";
	public static final String LOG_BAD_VERSION = "ClanSocket preset: unsupported schema version";
	public static final String LOG_SKIPPED_DENYLISTED = "ClanSocket preset: skipped denylisted key";
	public static final String LOG_HANDLER_FAILED = "ClanSocket preset: handler failed";
	public static final String LOG_SAVE_BLOCKED_CLAN_MODE = "ClanSocket preset: save blocked while in CLAN mode";

	public static final String EXCLUDED_PREFIX_RSPROFILE = "$";
	public static final String EXCLUDED_PREFIX_SNAP_HASH = "snap_hash.";
	public static final String EXCLUDED_PREFIX_WIKIAV = "wikiav.";

	private PresetConstants() {
	}
}

package com.clansocket.config.preset;

import java.util.Map;

import com.google.gson.JsonElement;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class PresetSchema
{
	private int version;
	private Map<String, JsonElement> values;
}

package com.clansocket.config.preset;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.client.config.ConfigManager;

import com.clansocket.ClanSocketConstants;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonSyntaxException;

@Singleton
public final class PresetCodec
{
	private final Gson gson;

	@Inject
	public PresetCodec(final Gson gson) {
		this.gson = gson;
	}

	public String encode(final PresetSchema schema)
	{
		return gson.toJson(schema);
	}

	public PresetSchema decode(final String json)
	{
		final PresetSchema schema;
		try
		{
			schema = gson.fromJson(json, PresetSchema.class);
		} catch (final JsonSyntaxException ex)
		{
			throw new IllegalArgumentException(PresetConstants.LOG_BAD_JSON, ex);
		}
		validateDecoded(schema);
		return schema;
	}

	private static void validateDecoded(final PresetSchema schema)
	{
		if (schema == null || schema.getValues() == null)
		{
			throw new IllegalArgumentException(PresetConstants.LOG_BAD_JSON);
		}
		if (schema.getVersion() != PresetConstants.SCHEMA_VERSION)
		{
			throw new IllegalArgumentException(PresetConstants.LOG_BAD_VERSION);
		}
		for (final Map.Entry<String, JsonElement> e : schema.getValues().entrySet())
		{
			if (!e.getValue().isJsonPrimitive())
			{
				throw new IllegalArgumentException(PresetConstants.LOG_BAD_JSON);
			}
		}
	}

	public String canonicalHash(final PresetSchema schema)
	{
		final Map<String, JsonElement> sorted = new TreeMap<>(schema.getValues());
		sorted.keySet().removeIf(PresetCodec::isDenylisted);
		return sha256Hex(gson.toJson(sorted));
	}

	public static boolean isDenylisted(final String key)
	{
		if (key.startsWith(PresetConstants.EXCLUDED_PREFIX_RSPROFILE)
		        || key.startsWith(PresetConstants.EXCLUDED_PREFIX_SNAP_HASH)
		        || key.startsWith(PresetConstants.EXCLUDED_PREFIX_WIKIAV))
		{
			return true;
		}
		return ClanSocketConstants.CONFIG_KEY_MODE.equals(key)
		        || ClanSocketConstants.CONFIG_KEY_SERVER_WS_URL.equals(key);
	}

	public static PresetSchema snapshot(final ConfigManager configManager)
	{
		final Map<String, JsonElement> values = new LinkedHashMap<>();
		final String prefix = ClanSocketConstants.CONFIG_GROUP + ".";
		final List<String> keys = configManager.getConfigurationKeys(prefix);
		for (final String fullKey : keys)
		{
			final String key = fullKey.startsWith(prefix) ? fullKey.substring(prefix.length()) : fullKey;
			if (isDenylisted(key))
			{
				continue;
			}
			final String val = configManager.getConfiguration(ClanSocketConstants.CONFIG_GROUP, key);
			if (val == null)
			{
				continue;
			}
			values.put(key, toJsonValue(val));
		}
		return new PresetSchema(PresetConstants.SCHEMA_VERSION, values);
	}

	private static JsonElement toJsonValue(final String s)
	{
		if ("true".equalsIgnoreCase(s) || "false".equalsIgnoreCase(s))
		{
			return new JsonPrimitive(Boolean.parseBoolean(s));
		}
		try
		{
			return new JsonPrimitive(Long.parseLong(s));
		} catch (final NumberFormatException ignored)
		{
		}
		try
		{
			return new JsonPrimitive(Double.parseDouble(s));
		} catch (final NumberFormatException ignored)
		{
		}
		return new JsonPrimitive(s);
	}

	private static String sha256Hex(final String s)
	{
		try
		{
			final MessageDigest md = MessageDigest.getInstance("SHA-256");
			final byte[] bytes = md.digest(s.getBytes(StandardCharsets.UTF_8));
			final StringBuilder sb = new StringBuilder(bytes.length * 2);
			for (final byte b : bytes)
			{
				sb.append(String.format("%02x", b));
			}
			return sb.toString();
		} catch (final NoSuchAlgorithmException ex)
		{
			throw new IllegalStateException(ex);
		}
	}
}

package com.clansocket.config.preset;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;

import com.clansocket.ClanSocketConstants;
import com.google.gson.JsonElement;

import lombok.Value;
import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
public final class PresetApplier
{
	public enum Source
	{
		LOCAL, CLAN
	}

	@Value
	public static class Applied
	{
		Set<String> changedKeys;

		public boolean changed(final String key)
		{
			return changedKeys.contains(key);
		}
	}

	private final ConfigManager configManager;
	private final EventBus eventBus;
	private final AtomicBoolean importing = new AtomicBoolean(false);
	private volatile Map<String, JsonElement> lastAppliedClanValues = Map.of();

	@Inject
	public PresetApplier(final ConfigManager configManager, final EventBus eventBus) {
		this.configManager = configManager;
		this.eventBus = eventBus;
	}

	public boolean isImporting()
	{
		return importing.get();
	}

	public Optional<String> lastClanValue(final String key)
	{
		final JsonElement el = lastAppliedClanValues.get(key);
		return el == null ? Optional.empty() : Optional.of(el.getAsString());
	}

	public void seedClanCanonicalFromCurrent()
	{
		this.lastAppliedClanValues = new HashMap<>(PresetCodec.snapshot(configManager).getValues());
	}

	public void apply(final PresetSchema schema, final Source source)
	{
		final Set<String> changed = new HashSet<>();
		importing.set(true);
		try
		{
			for (final Map.Entry<String, JsonElement> e : schema.getValues().entrySet())
			{
				applyOne(e.getKey(), e.getValue().getAsString(), changed);
			}
		} finally
		{
			importing.set(false);
		}
		if (source == Source.CLAN)
		{
			this.lastAppliedClanValues = new HashMap<>(schema.getValues());
		}
		eventBus.post(new Applied(changed));
	}

	private void applyOne(final String key, final String newValue, final Set<String> changed)
	{
		if (PresetCodec.isDenylisted(key))
		{
			log.debug("{} {}", PresetConstants.LOG_SKIPPED_DENYLISTED, key);
			return;
		}
		final String old = configManager.getConfiguration(ClanSocketConstants.CONFIG_GROUP, key);
		if (newValue.equals(old))
		{
			return;
		}
		configManager.setConfiguration(ClanSocketConstants.CONFIG_GROUP, key, newValue);
		changed.add(key);
	}
}

package com.clansocket.config;

import java.util.Collections;
import java.util.Optional;
import java.util.concurrent.ScheduledExecutorService;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;

import com.clansocket.CSConfigResolver;
import com.clansocket.ClanSocket;
import com.clansocket.ClanSocketConfig;
import com.clansocket.ClanSocketConstants;
import com.clansocket.config.preset.PresetApplier;
import com.clansocket.config.preset.PresetCodec;
import com.clansocket.panel.PanelStats;
import com.clansocket.panel.verify.ConsentRouter;

import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
public class ConfigEventBridge
{
	@Inject
	private ClanSocketConfig config;
	@Inject
	private ClanSocket socket;
	@Inject
	private ConfigManager configManager;
	@Inject
	private PanelStats panelStats;
	@Inject
	private ConsentRouter consentRouter;
	@Inject
	private PresetApplier presetApplier;
	@Inject
	private ScheduledExecutorService executor;

	@Subscribe
	public void onRuneScapeProfileChanged(final RuneScapeProfileChanged event)
	{
		executor.execute(panelStats::loadCounts);
	}

	@Subscribe
	public void onConfigChanged(final ConfigChanged event)
	{
		if (!ClanSocketConstants.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (presetApplier.isImporting())
		{
			return;
		}
		dispatchAfterGate(event.getKey(), event.getNewValue());
	}

	private void dispatchAfterGate(final String key, final String newValue)
	{
		if (ClanSocketConstants.CONFIG_KEY_MODE.equals(key))
		{
			handleModeChange(newValue);
			return;
		}
		if (ClanSocketConstants.CONFIG_KEY_SERVER_WS_URL.equals(key))
		{
			handleWsUrlChange();
			return;
		}
		if (revertedAsClanLocked(key, newValue))
		{
			return;
		}
		consentRouter.maybePrompt(key, newValue);
	}

	private boolean revertedAsClanLocked(final String key, final String newValue)
	{
		if (config.mode() != ClanSocketConfig.ConfigMode.CLAN || PresetCodec.isDenylisted(key))
		{
			return false;
		}
		final Optional<String> canonical = presetApplier.lastClanValue(key);
		if (canonical.isEmpty() || canonical.get().equals(newValue))
		{
			return false;
		}
		log.info("ClanSocket clan mode: reverting user edit on {}", key);
		configManager.setConfiguration(ClanSocketConstants.CONFIG_GROUP, key, canonical.get());
		return true;
	}

	private void handleModeChange(final String newValue)
	{
		if (ClanSocketConstants.CONFIG_MODE_CLAN.equals(newValue))
		{
			consentRouter.promptClanModeSwitch(this::requestClanConfig);
		}
	}

	private void requestClanConfig()
	{
		socket.send(Collections.singletonMap(ClanSocketConstants.WS_FIELD_TYPE,
		        ClanSocketConstants.WS_TYPE_CLAN_CONFIG_REQUEST));
	}

	@Subscribe
	public void onApplied(final PresetApplier.Applied event)
	{
		if (event.changed(ClanSocketConstants.CONFIG_KEY_SERVER_WS_URL))
		{
			handleWsUrlChange();
		}
	}

	private void handleWsUrlChange()
	{
		final String next = CSConfigResolver.serverWsUrl(config);
		log.info("ClanSocket WS endpoint changed → {}, reconnecting", next);
		socket.disconnect();
		socket.tryConnect(next);
	}
}

package com.clansocket.tracking.combat;

import javax.inject.Singleton;

@Singleton
public final class InteractionState
{
	private String lastKind;
	private Integer lastId;
	private String lastName;
	private int hpCache = -1;

	public void recordNpc(final int id, final String name)
	{
		lastKind = CombatConstants.INTERACT_KIND_NPC;
		lastId = id;
		lastName = name;
	}

	public void recordPlayer()
	{
		lastKind = CombatConstants.INTERACT_KIND_PLAYER;
		lastId = CombatConstants.INTERACT_DEDUP_PLAYER;
		lastName = null;
	}

	public void updateHp(final int hp)
	{
		if (hp > 0)
		{
			hpCache = hp;
		}
	}

	public String consumeKind()
	{
		return lastKind != null ? lastKind : CombatConstants.INTERACT_KIND_UNKNOWN;
	}

	public Integer consumeId()
	{
		return lastId;
	}

	public String consumeName()
	{
		return lastName;
	}

	public Integer consumeHpBefore()
	{
		return hpCache > 0 ? hpCache : null;
	}

	public void reset()
	{
		hpCache = -1;
		lastKind = null;
		lastId = null;
		lastName = null;
	}
}

package com.clansocket.tracking.combat;

import java.util.List;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.AbstractStateTracker;
import com.clansocket.bus.Hashes;
import com.clansocket.bus.primitive.IntObjectMap;
import com.clansocket.protocol.common.Payload;

@Singleton
public class SlayerTracker extends AbstractStateTracker
{
	@Inject
	private ClanSocketConfig config;

	private long lastSignature = Long.MIN_VALUE;

	private final IntObjectMap<String> regularTaskNameCache = new IntObjectMap<>();
	private final IntObjectMap<String> bossTaskNameCache = new IntObjectMap<>();
	private final IntObjectMap<String> areaNameCache = new IntObjectMap<>();

	@Override
	protected void onLoginScreen()
	{
		lastSignature = Long.MIN_VALUE;
	}

	@Override
	protected void emitFreshSnapshot()
	{
		lastSignature = Long.MIN_VALUE;
		emitSnapshot();
	}

	@Subscribe
	public void onVarbitChanged(final VarbitChanged event)
	{
		if (!config.streamSlayer())
		{
			return;
		}
		final boolean matched = CombatConstants.WATCHED_VARPS.contains(event.getVarpId())
		        || CombatConstants.WATCHED_VARBITS.contains(event.getVarbitId());
		if (!matched || !isLoggedIn())
		{
			return;
		}
		emitSnapshot();
	}

	private void emitSnapshot()
	{
		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		final int area = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		final int countOriginal = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		final int master = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		final int points = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		final int tasksCompleted = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		final int bossId = client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID);
		final int wildyTasksCompleted = client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
		final long sig = Hashes.rollingLong(count, target, area, countOriginal, master, points, tasksCompleted, bossId,
		        wildyTasksCompleted);
		if (sig == lastSignature || count > countOriginal || count > 0 && master == 0)
		{
			return;
		}
		lastSignature = sig;
		batcher.enqueue(new Payload("slayer", "hash", Long.toHexString(sig), "count", count, "target", target, "area",
		        area, "countOriginal", countOriginal, "master", master, "points", points, "tasksCompleted",
		        tasksCompleted, "bossId", bossId, "bossName", null, "wildyTasksCompleted", wildyTasksCompleted,
		        "masterName", CombatConstants.SLAYER_MASTERS.get(master), "targetName",
		        resolveTargetName(target, bossId), "areaName", resolveAreaName(area)));
	}

	private String resolveTargetName(final int taskId, final int bossId)
	{
		if (taskId <= 0)
		{
			return null;
		}
		final boolean isBossTask = taskId == CombatConstants.SLAYER_TASK_ID_BOSSES;
		final IntObjectMap<String> cache = isBossTask ? bossTaskNameCache : regularTaskNameCache;
		final int cacheKey = isBossTask ? bossId : taskId;
		final String cached = cache.get(cacheKey);
		if (cached != null)
		{
			return cached;
		}
		final Integer taskDbRow = isBossTask ? lookupBossTaskDbRow(bossId) : lookupRegularTaskDbRow(taskId);
		if (taskDbRow == null)
		{
			return null;
		}
		final String name = (String) client.getDBTableField(taskDbRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
		if (name != null)
		{
			cache.put(cacheKey, name);
		}
		return name;
	}

	private Integer lookupBossTaskDbRow(final int bossId)
	{
		final List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID,
		        DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, bossId);
		if (rows.isEmpty())
		{
			return null;
		}
		return (Integer) client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
	}

	private Integer lookupRegularTaskDbRow(final int taskId)
	{
		final List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0,
		        taskId);
		return rows.isEmpty() ? null : rows.get(0);
	}

	private String resolveAreaName(final int areaId)
	{
		if (areaId <= 0)
		{
			return null;
		}
		final String cached = areaNameCache.get(areaId);
		if (cached != null)
		{
			return cached;
		}
		final List<Integer> areaRows = client.getDBRowsByValue(DBTableID.SlayerArea.ID,
		        DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
		if (areaRows.isEmpty())
		{
			return null;
		}
		final String name = (String) client.getDBTableField(areaRows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER,
		        0)[0];
		if (name != null)
		{
			areaNameCache.put(areaId, name);
		}
		return name;
	}
}

package com.clansocket.tracking.combat;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.AbstractTracker;
import com.clansocket.protocol.common.Payload;
import com.clansocket.tracking.movement.LocationContext;
import com.clansocket.world.AreaResolver;

@Singleton
public class DeathHandler extends AbstractTracker
{
	@Inject
	private ClanSocketConfig config;
	@Inject
	private InteractionState interactionState;
	@Inject
	private AreaResolver areaResolver;
	@Inject
	private LocationContext locationContext;

	private PendingDeath pendingDeath;
	private int respawnStableTicks;
	private int ticksSinceDeath;

	@Subscribe
	public void onGameTick(final GameTick tick)
	{
		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		interactionState.updateHp(client.getBoostedSkillLevel(Skill.HITPOINTS));
		advanceRespawnTracking(locationContext.resolvePoint(local));
	}

	private void advanceRespawnTracking(final WorldPoint here)
	{
		if (pendingDeath == null || here == null)
		{
			return;
		}
		ticksSinceDeath++;
		if (pendingDeath.matchesRespawn(here))
		{
			respawnStableTicks++;
		} else
		{
			pendingDeath.setRespawn(here);
			respawnStableTicks = 1;
		}
		if (respawnStableTicks >= CombatConstants.RESPAWN_STABLE_TICKS
		        || ticksSinceDeath >= CombatConstants.RESPAWN_TIMEOUT_TICKS)
		{
			flushPendingDeath();
		}
	}

	private void flushPendingDeath()
	{
		final String deathName = pendingDeath.deathRegionId != null
		        ? areaResolver.resolve(pendingDeath.deathRegionId)
		        : null;
		final String respawnName = pendingDeath.respawnRegionId != null
		        ? areaResolver.resolve(pendingDeath.respawnRegionId)
		        : null;
		batcher.enqueue(buildDeathPayload(deathName, respawnName));
		pendingDeath = null;
		respawnStableTicks = 0;
		ticksSinceDeath = 0;
	}

	private Payload buildDeathPayload(final String deathName, final String respawnName)
	{
		return new Payload("death", "x", pendingDeath.deathX, "y", pendingDeath.deathY, "plane",
		        pendingDeath.deathPlane, "regionId", pendingDeath.deathRegionId, "regionName", deathName, "area",
		        deathName, "causeKind", pendingDeath.causeKind, "causeId", pendingDeath.causeId, "causeName",
		        pendingDeath.causeName, "causeCategory", pendingDeath.causeCategory, "hpBefore", pendingDeath.hpBefore,
		        "respawnX", pendingDeath.respawnX, "respawnY", pendingDeath.respawnY, "respawnPlane",
		        pendingDeath.respawnPlane, "respawnRegionId", pendingDeath.respawnRegionId, "world", client.getWorld(),
		        "causeCombatLevel", resolveCauseCombatLevel(), "respawnRegionName", respawnName, "respawnArea",
		        respawnName);
	}

	private Integer resolveCauseCombatLevel()
	{
		if (!CombatConstants.INTERACT_KIND_NPC.equals(pendingDeath.causeKind) || pendingDeath.causeId == null)
		{
			return null;
		}
		final net.runelite.api.NPCComposition comp = client.getNpcDefinition(pendingDeath.causeId);
		return comp != null ? comp.getCombatLevel() : null;
	}

	@Subscribe
	public void onActorDeath(final ActorDeath event)
	{
		if (!config.streamDeath() || !isLocalPlayer(event.getActor()))
		{
			return;
		}
		final WorldPoint p = locationContext.resolvePoint(client.getLocalPlayer());
		if (p == null)
		{
			return;
		}
		final String kind = interactionState.consumeKind();
		pendingDeath = new PendingDeath(p, kind, interactionState.consumeId(), interactionState.consumeName(),
		        classifyCauseCategory(kind), interactionState.consumeHpBefore());
		respawnStableTicks = 0;
		ticksSinceDeath = 0;
		interactionState.reset();
	}

	private String classifyCauseCategory(final String kind)
	{
		if (CombatConstants.INTERACT_KIND_PLAYER.equals(kind))
		{
			return CombatConstants.CAUSE_CATEGORY_PVP;
		}
		if (CombatConstants.INTERACT_KIND_NPC.equals(kind))
		{
			return CombatConstants.CAUSE_CATEGORY_PVM;
		}
		final WorldView wv = client.getTopLevelWorldView();
		if (wv != null && wv.isInstance())
		{
			return CombatConstants.CAUSE_CATEGORY_INSTANCE;
		}
		return CombatConstants.CAUSE_CATEGORY_ENVIRONMENT;
	}
}

package com.clansocket.tracking.combat;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Actor;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.AbstractTracker;
import com.clansocket.bus.Latched;
import com.clansocket.protocol.common.Payload;

@Singleton
public class CombatTracker extends AbstractTracker
{
	@Inject
	private ClanSocketConfig config;
	@Inject
	private InteractionState interactionState;
	@Inject
	private AttackStyleTracker attackStyleTracker;

	private final Latched<String> interactLatch = new Latched<>();

	@Subscribe
	public void onInteractingChanged(final InteractingChanged event)
	{
		if (!config.streamCombat() || !isLocalPlayer(event.getSource()))
		{
			return;
		}
		final Actor target = event.getTarget();
		if (target == null)
		{
			interactLatch.reset();
			return;
		}
		if (target instanceof NPC)
		{
			recordInteractNpc((NPC) target);
		} else if (target instanceof Player)
		{
			recordInteractPlayer();
		}
	}

	private void recordInteractNpc(final NPC npc)
	{
		interactionState.recordNpc(npc.getId(), npc.getName());
		emitInteracting(CombatConstants.INTERACT_KIND_NPC, npc.getId(), npc.getId(), npc.getName());
	}

	private void recordInteractPlayer()
	{
		interactionState.recordPlayer();
		emitInteracting(CombatConstants.INTERACT_KIND_PLAYER, CombatConstants.INTERACT_DEDUP_PLAYER, null, null);
	}

	private void emitInteracting(final String kind, final int dedupId, final Integer payloadId, final String name)
	{
		if (!interactLatch.update(kind + ":" + dedupId))
		{
			return;
		}
		batcher.enqueue(new Payload("interacting", "targetKind", kind, "targetId", payloadId, "targetName", name));
	}

	@Subscribe
	public void onHitsplatApplied(final HitsplatApplied event)
	{
		if (!config.streamCombat())
		{
			return;
		}
		final Hitsplat splat = event.getHitsplat();
		final Actor actor = event.getActor();
		if (splat == null || actor == null)
		{
			return;
		}
		if (isLocalPlayer(actor))
		{
			batcher.enqueue(new Payload("damage_taken", "amount", splat.getAmount(), "hitsplatType",
			        splat.getHitsplatType(), "hitsplatName", null, "sourceKind", interactionState.consumeKind(),
			        "sourceId", interactionState.consumeId(), "sourceName", interactionState.consumeName()));
			return;
		}
		if (splat.isMine())
		{
			emitDamageDealt(actor, splat);
		}
	}

	private void emitDamageDealt(final Actor actor, final Hitsplat splat)
	{
		final String style = attackStyleTracker.getCurrent();
		if (actor instanceof NPC)
		{
			final NPC npc = (NPC) actor;
			batcher.enqueue(new Payload("damage_dealt", "amount", splat.getAmount(), "hitsplatType",
			        splat.getHitsplatType(), "hitsplatName", null, "targetKind", CombatConstants.INTERACT_KIND_NPC,
			        "targetId", npc.getId(), "targetName", npc.getName(), "attackStyle", style));
		} else if (actor instanceof Player)
		{
			batcher.enqueue(new Payload("damage_dealt", "amount", splat.getAmount(), "hitsplatType",
			        splat.getHitsplatType(), "hitsplatName", null, "targetKind", CombatConstants.INTERACT_KIND_PLAYER,
			        "targetId", null, "targetName", null, "attackStyle", style));
		}
	}
}

