import java.util.List;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.NPCComposition;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.Text;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.AbstractTracker;
import com.clansocket.protocol.common.Payload;
import com.clansocket.protocol.inventory.Item;
import com.clansocket.tracking.inventory.ItemNames;
import com.clansocket.tracking.movement.LocationContext;

import lombok.RequiredArgsConstructor;

@Singleton
public class LootTracker extends AbstractTracker
{
	@Inject
	private ItemNames itemNames;
	@Inject
	private ClanSocketConfig config;
	@Inject
	private KillCountLookup killCounts;
	@Inject
	private LocationContext locationContext;

	@Subscribe(priority = -1f)
	public void onServerNpcLoot(final ServerNpcLoot event)
	{
		if (!config.streamLoot() || event == null || event.getComposition() == null)
		{
			return;
		}
		final NPCComposition npc = event.getComposition();
		enqueue(new Source(LootConstants.LOOT_TYPE_NPC, npc.getId(), npc.getName(), npc.getCombatLevel()),
		        event.getItems());
	}

	@Subscribe(priority = -1f)
	public void onLootReceived(final LootReceived event)
	{
		if (!config.streamLoot() || event == null || event.getType() == null)
		{
			return;
		}
		final String sourceType = event.getType().name();
		if (LootConstants.LOOT_TYPE_NPC.equals(sourceType))
		{
			return;
		}
		enqueue(new Source(sourceType, null, sanitizedSource(event), event.getCombatLevel()), event.getItems());
	}

	private void enqueue(final Source src, final Collection<ItemStack> items)
	{
		final String source = src.name == null ? null : Text.removeTags(src.name);
		final Integer kc = killCounts.bumpAndLookup(source, src.type);
		batcher.enqueue(new Payload("loot", "sourceType", src.type, "sourceId", src.id, "source", source, "sourceLevel",
		        src.level, "kc", kc, "items", snapshotItems(items), "where", locationContext.capture()));
	}

	private static String sanitizedSource(final LootReceived event)
	{
		if (LootConstants.LOOT_TYPE_PLAYER.equals(event.getType().name()))
		{
			return null;
		}
		return event.getName();
	}

	private List<Item> snapshotItems(final Collection<ItemStack> raw)
	{
		if (raw == null)
		{
			return Collections.emptyList();
		}
		final List<Item> out = new ArrayList<>(raw.size());
		for (final ItemStack it : raw)
		{
			if (it.getId() <= 0 || it.getQuantity() <= 0)
			{
				continue;
			}
			final int id = it.getId();
			out.add(new Item(id, it.getQuantity(), itemNames.resolve(id), itemNames.resolvePrice(id), -1, null));
		}
		return Collections.unmodifiableList(out);
	}

	@RequiredArgsConstructor
	private static final class Source
	{
		private final String type;
		private final Integer id;
		private final String name;
		private final int level;
	}
}

package com.clansocket.tracking.loot;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.client.config.ConfigManager;

import com.clansocket.ClanSocketConstants;
import com.clansocket.util.Strings;
import com.google.gson.Gson;
import com.google.gson.JsonObject;

@Singleton
public final class KillCountLookup
{
	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	private final ConcurrentMap<String, Integer> ourCounter = new ConcurrentHashMap<>();

	public Integer bumpAndLookup(final String npcName, final String lootType)
	{
		if (Strings.isEmpty(npcName))
		{
			return null;
		}
		final Integer broadcast = configManager.getRSProfileConfiguration(LootConstants.KILL_COUNT_GROUP,
		        npcName.toLowerCase(), int.class);
		if (broadcast != null)
		{
			return broadcast;
		}
		return bumpOurCounter(npcName, lootType);
	}

	private Integer bumpOurCounter(final String npcName, final String lootType)
	{
		final String key = npcName.toLowerCase();
		final int next = ourCounter.compute(key, (k, v) -> v != null ? v + 1 : seed(npcName, lootType) + 1);
		configManager.setRSProfileConfiguration(ClanSocketConstants.CONFIG_GROUP, LootConstants.OUR_KC_PREFIX + key,
		        next);
		return next;
	}

	private int seed(final String npcName, final String lootType)
	{
		final Integer persisted = configManager.getRSProfileConfiguration(ClanSocketConstants.CONFIG_GROUP,
		        LootConstants.OUR_KC_PREFIX + npcName.toLowerCase(), int.class);
		if (persisted != null)
		{
			return persisted;
		}
		final Integer historical = readFromLootTracker(npcName, lootType);
		return historical == null ? 0 : historical;
	}

	private Integer readFromLootTracker(final String npcName, final String lootType)
	{
		if (Strings.isEmpty(lootType))
		{
			return null;
		}
		final String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			return null;
		}
		final String key = LootConstants.LOOT_DROPS_KEY_PREFIX + lootType + "_" + npcName;
		final String json = configManager.getConfiguration(LootConstants.LOOT_TRACKER_GROUP, profile, key);
		if (json == null)
		{
			return null;
		}
		return parseKills(json);
	}

	private Integer parseKills(final String json)
	{
		try
		{
			final JsonObject obj = gson.fromJson(json, JsonObject.class);
			if (obj == null || !obj.has(LootConstants.LOOT_TRACKER_KILLS_FIELD))
			{
				return null;
			}
			return obj.get(LootConstants.LOOT_TRACKER_KILLS_FIELD).getAsInt();
		} catch (final RuntimeException ignored)
		{
			return null;
		}
	}
}

package com.clansocket.tracking.movement;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.Hashes;
import com.clansocket.bus.primitive.LatchedSnapshotTracker;
import com.clansocket.protocol.common.Payload;
import com.clansocket.world.AreaResolver;

@Singleton
public class LocationTracker extends LatchedSnapshotTracker<Long>
{
	@Inject
	private AreaResolver areaResolver;
	@Inject
	private LocationContext locationContext;
	@Inject
	private ClanSocketConfig config;

	private int lastWorld = -1;

	@Subscribe
	public void onGameTick(final GameTick tick)
	{
		if (!config.streamLocation())
		{
			return;
		}
		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		detectWorldHop();
		final WorldPoint p = locationContext.resolvePoint(local);
		if (p == null)
		{
			return;
		}
		if (!latch.update(Hashes.rollingLong(p.getX(), p.getY(), p.getPlane())))
		{
			return;
		}
		final String name = areaResolver.resolve(p.getRegionID());
		batcher.enqueue(new Payload("location", "x", p.getX(), "y", p.getY(), "plane", p.getPlane(), "region",
		        p.getRegionID(), "regionName", name, "area", name));
	}

	private void detectWorldHop()
	{
		final int world = client.getWorld();
		if (world <= 0)
		{
			return;
		}
		if (lastWorld > 0 && world != lastWorld)
		{
			batcher.enqueue(new Payload("world_hop", "fromWorld", lastWorld, "toWorld", world));
		}
		lastWorld = world;
	}
}

package com.clansocket.tracking.movement;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

import com.clansocket.protocol.common.Where;
import com.clansocket.world.AreaResolver;

@Singleton
public final class LocationContext
{
	@Inject
	private Client client;
	@Inject
	private AreaResolver areaResolver;

	public Where capture()
	{
		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}
		final WorldPoint p = resolvePoint(local);
		if (p == null)
		{
			return null;
		}
		final int regionId = p.getRegionID();
		final String name = areaResolver.resolve(regionId);
		return new Where(client.getWorld(), p.getX(), p.getY(), p.getPlane(), regionId, name, name);
	}

	public WorldPoint resolvePoint(final Player local)
	{
		final WorldView wv = client.getTopLevelWorldView();
		if (wv != null && wv.isInstance())
		{
			final LocalPoint lp = local.getLocalLocation();
			if (lp != null)
			{
				return WorldPoint.fromLocalInstance(client, lp);
			}
		}
		return local.getWorldLocation();
	}
}

package com.clansocket.tracking.state;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Prayer;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.primitive.IntIntMap;
import com.clansocket.bus.primitive.LatchedSnapshotTracker;
import com.clansocket.protocol.common.Payload;
import com.clansocket.protocol.state.PrayerActive;

@Singleton
public class PrayerTracker extends LatchedSnapshotTracker<Long>
{
	private static final IntIntMap VARBIT_TO_ORDINAL;
	private static final String[] PRAYER_NAMES;

	static
	{
		if (Prayer.values().length > Long.SIZE)
		{
			throw new IllegalStateException("Prayer enum has " + Prayer.values().length
			        + " values, exceeds long bitmask capacity (" + Long.SIZE + ")");
		}
		VARBIT_TO_ORDINAL = new IntIntMap(Prayer.values().length, StateConstants.VARBIT_MISS);
		PRAYER_NAMES = new String[Prayer.values().length];
		for (final Prayer p : Prayer.values())
		{
			VARBIT_TO_ORDINAL.put(p.getVarbit(), p.ordinal());
			PRAYER_NAMES[p.ordinal()] = p.name();
		}
	}

	@Inject
	private ClanSocketConfig config;

	private long activeMask;

	@Override
	protected void onLoginScreen()
	{
		super.onLoginScreen();
		activeMask = 0L;
	}

	@Override
	protected void onLoggedIn()
	{
		seedMaskFromClient();
	}

	@Override
	protected void emitFreshSnapshot()
	{
		super.emitFreshSnapshot();
		seedMaskFromClient();
	}

	@Subscribe
	public void onVarbitChanged(final VarbitChanged event)
	{
		final int ordinal = VARBIT_TO_ORDINAL.get(event.getVarbitId());
		if (ordinal == StateConstants.VARBIT_MISS)
		{
			return;
		}
		final long bit = 1L << ordinal;
		activeMask = event.getValue() == 1 ? activeMask | bit : activeMask & ~bit;
	}

	@Subscribe
	public void onGameTick(final GameTick tick)
	{
		if (!config.streamPrayer() || !isLoggedIn())
		{
			return;
		}
		if (!latch.update(activeMask))
		{
			return;
		}
		emit(activeMask);
	}

	private void seedMaskFromClient()
	{
		long mask = 0L;
		for (final Prayer p : Prayer.values())
		{
			if (client.getVarbitValue(p.getVarbit()) == 1)
			{
				mask |= 1L << p.ordinal();
			}
		}
		activeMask = mask;
	}

	private void emit(final long mask)
	{
		final List<PrayerActive> active = new ArrayList<>(Long.bitCount(mask));
		long m = mask;
		while (m != 0L)
		{
			final int bit = Long.numberOfTrailingZeros(m);
			active.add(new PrayerActive(bit, PRAYER_NAMES[bit]));
			m &= m - 1L;
		}
		batcher.enqueue(
		        new Payload("prayers", "hash", Long.toHexString(mask), "active", Collections.unmodifiableList(active)));
	}
}

