package com.clansocket.tracking.progression;

import java.util.Set;

public final class ProgressionConstants
{
	public static final int LOGIN_WARMUP_TICKS = 16;
	public static final int QUEST_WARMUP_TICKS = 8;

	static final String CLUE_PREFIX = "You have completed ";
	static final String CLUE_SUFFIX_PLURAL = " Treasure Trails.";
	static final String CLUE_SUFFIX_SINGULAR = " Treasure Trail.";
	static final int DECIMAL_BASE = 10;

	static final String CLUE_ITEM_PREFIX_CLUE = "Clue scroll (";
	static final String CLUE_ITEM_PREFIX_CHALLENGE = "Challenge scroll (";
	static final String CLUE_ITEM_PREFIX_TREASURE = "Treasure scroll (";
	static final String CLUE_MENU_READ = "Read";

	static final Set<String> CLUE_TIERS = Set.of("beginner", "easy", "medium", "hard", "elite", "master");

	private ProgressionConstants() {
	}
}

package com.clansocket.tracking.progression;

import java.util.Locale;
import java.util.Optional;

import com.clansocket.protocol.common.Payload;
import com.clansocket.protocol.common.Where;

final class ClueCompletionParser
{
	private ClueCompletionParser() {
	}

	static Optional<Payload> parse(final String text, final Where where)
	{
		if (text == null || !text.startsWith(ProgressionConstants.CLUE_PREFIX))
		{
			return Optional.empty();
		}
		final String suffix = matchSuffix(text);
		if (suffix == null)
		{
			return Optional.empty();
		}
		final int tierEnd = text.length() - suffix.length();
		final int[] parsedDigits = readDigits(text, ProgressionConstants.CLUE_PREFIX.length(), tierEnd);
		if (parsedDigits == null)
		{
			return Optional.empty();
		}
		final String tier = extractTier(text, parsedDigits[1], tierEnd);
		if (tier == null)
		{
			return Optional.empty();
		}
		return Optional.of(new Payload("clue_completed", "tier", tier.toUpperCase(Locale.ROOT), "total",
		        parsedDigits[0], "cluesCompletedBefore", Math.max(0, parsedDigits[0] - 1), "where", where));
	}

	private static String extractTier(final String text, final int afterDigits, final int tierEnd)
	{
		if (afterDigits >= tierEnd || text.charAt(afterDigits) != ' ')
		{
			return null;
		}
		final String tier = text.substring(afterDigits + 1, tierEnd);
		return ProgressionConstants.CLUE_TIERS.contains(tier) ? tier : null;
	}

	private static String matchSuffix(final String text)
	{
		if (text.endsWith(ProgressionConstants.CLUE_SUFFIX_PLURAL))
		{
			return ProgressionConstants.CLUE_SUFFIX_PLURAL;
		}
		if (text.endsWith(ProgressionConstants.CLUE_SUFFIX_SINGULAR))
		{
			return ProgressionConstants.CLUE_SUFFIX_SINGULAR;
		}
		return null;
	}

	private static int[] readDigits(final String text, final int start, final int end)
	{
		int total = 0;
		int i = start;
		while (i < end)
		{
			final char c = text.charAt(i);
			if (c < '0' || c > '9')
			{
				break;
			}
			total = total * ProgressionConstants.DECIMAL_BASE + (c - '0');
			i++;
		}
		if (i == start)
		{
			return null;
		}
		return new int[]{total, i};
	}
}

package com.clansocket.tracking.progression;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.AbstractStateTracker;
import com.clansocket.bus.Hashes;
import com.clansocket.protocol.common.Payload;
import com.clansocket.protocol.diaries.DiaryEntry;
import com.clansocket.tracking.movement.LocationContext;

@Singleton
public class DiaryTracker extends AbstractStateTracker
{
	@Inject
	private ClanSocketConfig config;
	@Inject
	private LocationContext locationContext;

	private final Map<Integer, Boolean> lastState = new HashMap<>();
	private int loginTicks;
	private boolean dataSettled;

	@Override
	protected void onLoginScreen()
	{
		dataSettled = false;
		loginTicks = 0;
		lastState.clear();
	}

	@Override
	protected void emitFreshSnapshot()
	{
		dataSettled = false;
		loginTicks = 0;
	}

	@Subscribe
	public void onGameTick(final GameTick tick)
	{
		if (!config.streamDiaries() || !isLoggedIn() || dataSettled)
		{
			return;
		}
		loginTicks++;
		if (loginTicks >= ProgressionConstants.LOGIN_WARMUP_TICKS)
		{
			emitSnapshot();
			dataSettled = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(final VarbitChanged event)
	{
		if (!config.streamDiaries())
		{
			return;
		}
		final DiaryEntries.Entry e = DiaryEntries.BY_VARBIT.get(event.getVarbitId());
		if (e == null || !isLoggedIn())
		{
			return;
		}
		final boolean now = client.getVarbitValue(e.varbit) > 0;
		final Boolean prev = lastState.put(e.varbit, now);
		if (dataSettled && now && prev != null && !prev)
		{
			batcher.enqueue(new Payload("diary_completed", "region", e.region, "tier", e.tier, "diariesCompletedBefore",
			        countTierCompletedBefore(e), "where", locationContext.capture()));
		}
	}

	private int countTierCompletedBefore(final DiaryEntries.Entry justCompleted)
	{
		int count = 0;
		for (final DiaryEntries.Entry other : DiaryEntries.ALL)
		{
			if (other.varbit == justCompleted.varbit || !other.tier.equals(justCompleted.tier))
			{
				continue;
			}
			final Boolean state = lastState.get(other.varbit);
			if (state != null && state)
			{
				count++;
			}
		}
		return count;
	}

	private void emitSnapshot()
	{
		if (!config.streamDiaries() || !isLoggedIn())
		{
			return;
		}
		final List<DiaryEntry> out = new ArrayList<>(DiaryEntries.ALL.length);
		for (final DiaryEntries.Entry e : DiaryEntries.ALL)
		{
			final boolean complete = client.getVarbitValue(e.varbit) > 0;
			lastState.put(e.varbit, complete);
			out.add(new DiaryEntry(e.region, e.tier, complete));
		}
		final String hash = Hashes.ofMapped(out, e -> new Object[]{e.complete});
		batcher.enqueue(new Payload("diaries", "hash", hash, "diaries", Collections.unmodifiableList(out)));
	}
}

