	        "MECHANICAL", 5, "RESTRICTION", 6, "SPEED");

	public static final int[] COMPLETION_VARP_IDS = {VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1,
