package com.clansocket.tracking.progression.combatachievements.progress;

import java.util.HashSet;
import java.util.Set;

import net.runelite.api.Client;

import com.clansocket.tracking.progression.combatachievements.CombatAchievementConstants;

final class CombatAchievementCompletionState
{
	private CombatAchievementCompletionState() {
	}

	static Set<Integer> readCompletedTaskIds(final Client client)
	{
		final Set<Integer> completed = new HashSet<>();
		for (int varpIdx = 0; varpIdx < CombatAchievementConstants.COMPLETION_VARP_IDS.length; varpIdx++)
		{
			final int varp = client.getVarpValue(CombatAchievementConstants.COMPLETION_VARP_IDS[varpIdx]);
			if (varp == 0)
			{
				continue;
			}
			final int base = varpIdx * CombatAchievementConstants.BITS_PER_VARP;
			for (int bit = 0; bit < CombatAchievementConstants.BITS_PER_VARP; bit++)
			{
				if ((varp & (1 << bit)) != 0)
				{
					completed.add(base + bit);
				}
			}
		}
		return completed;
	}
}

package com.clansocket.tracking.progression.combatachievements.progress;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

import com.clansocket.bus.Hashes;
import com.clansocket.protocol.common.Payload;
import com.clansocket.protocol.progression.CatalogEntry;
import com.clansocket.protocol.progression.CompletedTask;
import com.clansocket.tracking.progression.combatachievements.CombatAchievementConstants;

final class CombatAchievementSnapshotBuilder
{
	private CombatAchievementSnapshotBuilder() {
	}

	static Payload build(final Set<Integer> completed, final Map<Integer, CatalogEntry> catalogById)
	{
		final Map<String, Integer> tierCounts = countByTier(completed, catalogById);
		final List<Integer> sorted = new ArrayList<>(completed);
		Collections.sort(sorted);
		final List<CompletedTask> tasks = new ArrayList<>(sorted.size());
		for (final Integer taskId : sorted)
		{
			final CatalogEntry entry = catalogById.get(taskId);
			tasks.add(new CompletedTask(taskId, entry == null ? null : entry.name));
		}
		return new Payload("combat_achievements_snapshot", "hash", Hashes.of(tierCounts, sorted), "tierCounts",
		        Collections.unmodifiableMap(tierCounts), "totalCompleted", completed.size(), "completedTasks",
		        Collections.unmodifiableList(tasks));
	}

	private static Map<String, Integer> countByTier(final Set<Integer> completed,
	        final Map<Integer, CatalogEntry> catalogById)
	{
		final Map<String, Integer> tierCounts = new LinkedHashMap<>();
		for (final String tier : CombatAchievementConstants.TIER_NAMES)
		{
			tierCounts.put(tier, 0);
		}
		for (final Integer taskId : completed)
		{
			final CatalogEntry entry = catalogById.get(taskId);
			if (entry != null)
			{
				tierCounts.merge(entry.tier, 1, Integer::sum);
			}
		}
		return tierCounts;
	}
}

package com.clansocket.tracking.progression.combatachievements.progress;

import java.util.Collections;
import java.util.Set;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.AbstractStateTracker;
import com.clansocket.protocol.common.Payload;
import com.clansocket.protocol.progression.CatalogEntry;
import com.clansocket.tracking.progression.combatachievements.CombatAchievementConstants;
import com.clansocket.tracking.progression.combatachievements.CombatAchievementPrimer;

@Singleton
public class CombatAchievementProgressTracker extends AbstractStateTracker
{
	@Inject
	private ClientThread clientThread;
	@Inject
	private ClanSocketConfig config;
	@Inject
	private CombatAchievementPrimer primer;

	private Set<Integer> lastCompleted = Collections.emptySet();
	private boolean snapshotEmitted;

	@Override
	protected void onLoginScreen()
	{
		snapshotEmitted = false;
		lastCompleted = Collections.emptySet();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(final RuneScapeProfileChanged event)
	{
		snapshotEmitted = false;
		lastCompleted = Collections.emptySet();
	}

	@Override
	protected void emitFreshSnapshot()
	{
		snapshotEmitted = false;
	}

	@Subscribe
	public void onGameTick(final GameTick tick)
	{
		if (!isLoggedIn() || snapshotEmitted || !config.streamCombatAchievements() || !primer.isCatalogLoaded())
		{
			return;
		}
		lastCompleted = CombatAchievementCompletionState.readCompletedTaskIds(client);
		batcher.enqueue(CombatAchievementSnapshotBuilder.build(lastCompleted, primer.catalog()));
		snapshotEmitted = true;
	}

	@Subscribe
	public void onChatMessage(final ChatMessage event)
	{
		if (config.streamCombatAchievements() && isCompletionMessage(event))
		{
			clientThread.invokeLater(this::detectAndEmitCompletions);
		}
	}

	private void detectAndEmitCompletions()
	{
		if (!primer.isCatalogLoaded())
		{
			return;
		}
		final Set<Integer> current = CombatAchievementCompletionState.readCompletedTaskIds(client);
		if (emitNewCompletions(current))
		{
			lastCompleted = current;
			batcher.enqueue(CombatAchievementSnapshotBuilder.build(current, primer.catalog()));
		}
	}

	private boolean emitNewCompletions(final Set<Integer> current)
	{
		final int pointsBefore = computePointsBefore();
		boolean any = false;
		for (final Integer taskId : current)
		{
			if (lastCompleted.contains(taskId))
			{
				continue;
			}
			final CatalogEntry entry = primer.catalog().get(taskId);
			if (entry == null)
			{
				continue;
			}
			batcher.enqueue(new Payload("combat_achievement_completed", "taskId", entry.taskId, "name", entry.name,
			        "tier", entry.tier, "taskType", entry.taskType, "points", entry.points, "bossId", entry.bossId,
			        "bossName", entry.bossName, "pointsBefore", pointsBefore));
			any = true;
		}
		return any;
	}

	private int computePointsBefore()
	{
		int sum = 0;
		for (final Integer taskId : lastCompleted)
		{
			final CatalogEntry priorEntry = primer.catalog().get(taskId);
			if (priorEntry != null)
			{
				sum += priorEntry.points;
			}
		}
		return sum;
	}

	private static boolean isCompletionMessage(final ChatMessage event)
	{
		final ChatMessageType t = event.getType();
		if (t != ChatMessageType.GAMEMESSAGE && t != ChatMessageType.SPAM)
		{
			return false;
		}
		final String msg = event.getMessage();
		return msg != null && msg.contains(CombatAchievementConstants.CHAT_COMPLETION_PREFIX)
		        && msg.contains(CombatAchievementConstants.CHAT_COMPLETION_TASK_TOKEN);
	}
}

package com.clansocket.tracking.progression;

import java.util.Locale;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.AbstractTracker;
import com.clansocket.protocol.common.Payload;
import com.clansocket.tracking.inventory.ItemNames;
import com.clansocket.tracking.movement.LocationContext;

@Singleton
public class ClueOpenedTracker extends AbstractTracker
{
	private static final String[] CLUE_PREFIXES = {ProgressionConstants.CLUE_ITEM_PREFIX_CLUE,
	        ProgressionConstants.CLUE_ITEM_PREFIX_CHALLENGE, ProgressionConstants.CLUE_ITEM_PREFIX_TREASURE};

	@Inject
	private ItemNames itemNames;
	@Inject
	private ClanSocketConfig config;
	@Inject
	private LocationContext locationContext;

	@Subscribe
	public void onMenuOptionClicked(final MenuOptionClicked event)
	{
		if (!config.streamClues() || !ProgressionConstants.CLUE_MENU_READ.equals(event.getMenuOption()))
		{
			return;
		}
		final int itemId = event.getItemId();
		if (itemId <= 0)
		{
			return;
		}
		final String name = itemNames.resolve(itemId);
		if (name == null)
		{
			return;
		}
		final String tier = extractTier(name);
		if (tier == null)
		{
			return;
		}
		batcher.enqueue(new Payload("clue_opened", "tier", tier.toUpperCase(Locale.ROOT), "itemId", itemId, "itemName",
		        name, "where", locationContext.capture()));
	}

	private static String extractTier(final String name)
	{
		for (final String prefix : CLUE_PREFIXES)
		{
			if (!name.startsWith(prefix))
			{
				continue;
			}
			final int end = name.indexOf(')', prefix.length());
			if (end < 0)
			{
				continue;
			}
			final String tier = name.substring(prefix.length(), end);
			if (ProgressionConstants.CLUE_TIERS.contains(tier))
			{
				return tier;
			}
		}
		return null;
	}
}

package com.clansocket.tracking.progression.xp;

import javax.inject.Singleton;

import net.runelite.api.Skill;

import com.clansocket.bus.Hashes;
import com.clansocket.bus.primitive.ArmedState;

@Singleton
public class XpState extends ArmedState
{
	private final int[] lastXp = new int[Skill.values().length];
	private final int[] lastRealLevel = new int[Skill.values().length];

	public int getXp(final Skill skill)
	{
		return lastXp[skill.ordinal()];
	}

	public void setXp(final Skill skill, final int xp)
	{
		lastXp[skill.ordinal()] = xp;
	}

	public int getRealLevel(final Skill skill)
	{
		return lastRealLevel[skill.ordinal()];
	}

	public void setRealLevel(final Skill skill, final int level)
	{
		lastRealLevel[skill.ordinal()] = level;
	}

	public String snapshotHash()
	{
		return Hashes.of(lastXp, lastRealLevel);
	}

	@Override
	public void clear()
	{
		for (int i = 0; i < lastXp.length; i++)
		{
			lastXp[i] = 0;
			lastRealLevel[i] = 0;
		}
		disarm();
	}
}

package com.clansocket.tracking.progression.xp;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.EventBatcher;
import com.clansocket.protocol.common.Payload;
import com.clansocket.tracking.movement.LocationContext;

@Singleton
public class LevelUpTracker
{
	@Inject
	private EventBatcher batcher;
	@Inject
	private XpState state;
	@Inject
	private ClanSocketConfig config;
	@Inject
	private LocationContext locationContext;

	@Subscribe
	public void onStatChanged(final StatChanged event)
	{
		if (!config.streamLevelUps() || !state.isArmed())
		{
			return;
		}
		final Skill skill = event.getSkill();
		final int realLevel = event.getLevel();
		final int prevLevel = state.getRealLevel(skill);
		final int currentXp = event.getXp();
		final int prevXp = state.getXp(skill);
		if (realLevel > prevLevel && prevLevel > 0)
		{
			batcher.enqueue(new Payload("level_up", "skill", skill.name(), "level", realLevel, "levelBefore", prevLevel,
			        "xpBefore", (long) prevXp, "xpGained", currentXp - prevXp, "where", locationContext.capture()));
		}
		state.setRealLevel(skill, realLevel);
	}
}

package com.clansocket.tracking.progression.xp;

import java.util.EnumMap;
import java.util.Map;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.EventBatcher;
import com.clansocket.protocol.common.Payload;

@Singleton
public class XpDeltaTracker
{
	@Inject
	private Client client;
	@Inject
	private EventBatcher batcher;
	@Inject
	private XpState state;
	@Inject
	private ClanSocketConfig config;

	private final Map<Skill, Integer> pending = new EnumMap<>(Skill.class);

	@Subscribe
	public void onGameStateChanged(final GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			pending.clear();
		}
	}

	@Subscribe
	public void onStatChanged(final StatChanged event)
	{
		if (!config.streamXpGains() || !state.isArmed())
		{
			return;
		}
		final Skill skill = event.getSkill();
		final int xp = event.getXp();
		final int prev = state.getXp(skill);
		if (xp > prev)
		{
			pending.merge(skill, xp - prev, Integer::sum);
		}
		state.setXp(skill, xp);
	}

	@Subscribe
	public void onGameTick(final GameTick tick)
	{
		if (!config.streamXpGains() || pending.isEmpty())
		{
			return;
		}
		for (final Map.Entry<Skill, Integer> e : pending.entrySet())
		{
			final Skill skill = e.getKey();
			batcher.enqueue(new Payload("xp_gained", "skill", skill.name(), "xp", client.getSkillExperience(skill),
			        "delta", e.getValue()));
		}
		pending.clear();
	}
}

