package com.clansocket.tracking.progression.collectionlog;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.GameChatTracker;
import com.clansocket.protocol.common.Payload;
import com.clansocket.tracking.movement.LocationContext;
import com.clansocket.tracking.social.ChatTextSanitizer;

@Singleton
public class CollectionLogTracker extends GameChatTracker
{
	@Inject
	private ClanSocketConfig config;
	@Inject
	private LocationContext locationContext;

	private boolean notificationStarted;

	@Override
	protected void handleGameChat(final String text)
	{
		if (!config.streamCollectionLog())
		{
			return;
		}
		final String stripped = ChatTextSanitizer.sanitize(text);
		if (!stripped.startsWith(CollectionLogConstants.CHAT_PREFIX))
		{
			return;
		}
		final String itemName = stripped.substring(CollectionLogConstants.CHAT_PREFIX.length()).trim();
		if (itemName.isEmpty())
		{
			return;
		}
		emit(itemName);
	}

	@Subscribe
	public void onScriptPreFired(final ScriptPreFired event)
	{
		switch (event.getScriptId())
		{
			case ScriptID.NOTIFICATION_START :
				notificationStarted = true;
				break;
			case ScriptID.NOTIFICATION_DELAY :
				if (notificationStarted)
				{
					handleNotification();
					notificationStarted = false;
				}
				break;
			default :
				break;
		}
	}

	private void handleNotification()
	{
		if (!config.streamCollectionLog())
		{
			return;
		}
		final String title = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
		if (title == null || !CollectionLogConstants.NOTIFICATION_TITLE.equalsIgnoreCase(title))
		{
			return;
		}
		final String body = client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN);
		if (body == null)
		{
			return;
		}
		final String itemName = parseItemName(body);
		if (itemName.isEmpty())
		{
			return;
		}
		emit(itemName);
	}

	private void emit(final String itemName)
	{
		batcher.enqueue(new Payload("collection_log_entry", "itemName", itemName, "itemId", null, "where",
		        locationContext.capture(), "category", null, "sourceKind", null));
	}

	private static String parseItemName(final String body)
	{
		final String stripped = ChatTextSanitizer.sanitize(body);
		if (!stripped.startsWith(CollectionLogConstants.NOTIFICATION_PREFIX))
		{
			return "";
		}
		return stripped.substring(CollectionLogConstants.NOTIFICATION_PREFIX.length()).trim();
	}
}

package com.clansocket.tracking.progression.collectionlog;

public final class CollectionLogConstants
{
	static final String NOTIFICATION_TITLE = "Collection log";
	static final String NOTIFICATION_PREFIX = "New item:";
	public static final String CHAT_PREFIX = "New item added to your collection log: ";

	static final int ITEM_SCRIPT_ID = 4100;
	static final int SETUP_SCRIPT_ID = 7797;
	static final int AUTO_SCRAPE_WIDGET_ID = 40697932;
	static final int AUTO_SCRAPE_RUN_SCRIPT_ID = 2240;
	static final int FLUSH_QUIESCENCE_TICKS = 3;
	static final int MIN_SCRIPT_ARGS = 3;
	static final int ARG_INDEX_ITEM_ID = 1;
	static final int ARG_INDEX_QUANTITY = 2;

	private CollectionLogConstants() {
	}
}

package com.clansocket.tracking.progression.collectionlog;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import com.clansocket.bus.Hashes;
import com.clansocket.bus.primitive.IntIntMap;
import com.clansocket.protocol.collection.CollectionLogItem;
import com.clansocket.protocol.common.Payload;
import com.clansocket.tracking.inventory.ItemNames;

final class CollectionLogSnapshotBuilder
{
	private CollectionLogSnapshotBuilder() {
	}

	static Payload build(final IntIntMap accumulator, final ItemNames itemNames)
	{
		final List<CollectionLogItem> items = sortedItems(accumulator, itemNames);
		return new Payload("collection_log_snapshot", "hash",
		        Long.toHexString(Hashes.pairsLong(items, i -> i.itemId, i -> i.quantity)), "itemCount", items.size(),
		        "items", Collections.unmodifiableList(items));
	}

	private static List<CollectionLogItem> sortedItems(final IntIntMap accumulator, final ItemNames itemNames)
	{
		final int[] ids = accumulator.keys();
		Arrays.sort(ids);
		final List<CollectionLogItem> items = new ArrayList<>(ids.length);
		for (final int id : ids)
		{
			items.add(new CollectionLogItem(id, accumulator.get(id), itemNames.resolve(id), itemNames.resolvePrice(id),
			        null));
		}
		return items;
	}
}

package com.clansocket.tracking.progression.collectionlog;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.AbstractStateTracker;
import com.clansocket.bus.primitive.IntIntMap;
import com.clansocket.tracking.inventory.ItemNames;

import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class CollectionLogSnapshotTracker extends AbstractStateTracker
{
	@Inject
	private ClanSocketConfig config;
	@Inject
	private ItemNames itemNames;

	private final IntIntMap accumulator = new IntIntMap();
	private int lastItemTick = -1;
	private boolean autoScrapeFired;

	@Override
	protected void onLoginScreen()
	{
		reset();
	}

	@Override
	protected void onOtherGameState(final GameState state)
	{
		if (state != GameState.HOPPING)
		{
			reset();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(final RuneScapeProfileChanged event)
	{
		reset();
	}

	@Subscribe
	public void onVarbitChanged(final VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.COLLECTION_POH_HOST_BOOK_OPEN && isAdventureLogOpen())
		{
			log.debug("ClanSocket clog: adventure log opened mid-scrape, discarding partial accumulator");
			reset();
		}
	}

	@Subscribe
	public void onScriptPreFired(final ScriptPreFired event)
	{
		if (event.getScriptId() != CollectionLogConstants.ITEM_SCRIPT_ID || isAdventureLogOpen()
		        || !config.streamCollectionLog())
		{
			return;
		}
		final int[] item = extractScriptArgs(event);
		if (item == null)
		{
			return;
		}
		accumulator.put(item[0], item[1]);
		lastItemTick = client.getTickCount();
	}

	@Subscribe
	public void onScriptPostFired(final ScriptPostFired event)
	{
		if (event.getScriptId() != CollectionLogConstants.SETUP_SCRIPT_ID)
		{
			return;
		}
		if (isAdventureLogOpen())
		{
			accumulator.clear();
			return;
		}
		if (autoScrapeFired || !config.streamCollectionLog())
		{
			return;
		}
		autoScrapeFired = true;
		client.menuAction(-1, CollectionLogConstants.AUTO_SCRAPE_WIDGET_ID, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(CollectionLogConstants.AUTO_SCRAPE_RUN_SCRIPT_ID);
	}

	@Subscribe
	public void onGameTick(final GameTick tick)
	{
		if (lastItemTick < 0 || accumulator.isEmpty()
		        || client.getTickCount() - lastItemTick < CollectionLogConstants.FLUSH_QUIESCENCE_TICKS)
		{
			return;
		}
		if (!config.streamCollectionLog())
		{
			reset();
			return;
		}
		batcher.enqueue(CollectionLogSnapshotBuilder.build(accumulator, itemNames));
		log.debug("ClanSocket clog snapshot flushed: {} items", accumulator.size());
		reset();
	}

	private void reset()
	{
		accumulator.clear();
		lastItemTick = -1;
		autoScrapeFired = false;
	}

	private boolean isAdventureLogOpen()
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}

	private static int[] extractScriptArgs(final ScriptPreFired event)
	{
		final Object[] args = event.getScriptEvent() == null ? null : event.getScriptEvent().getArguments();
		if (args == null || args.length < CollectionLogConstants.MIN_SCRIPT_ARGS
		        || !(args[CollectionLogConstants.ARG_INDEX_ITEM_ID] instanceof Integer)
		        || !(args[CollectionLogConstants.ARG_INDEX_QUANTITY] instanceof Integer))
		{
			return null;
		}
		final int qty = (Integer) args[CollectionLogConstants.ARG_INDEX_QUANTITY];
		return qty <= 0 ? null : new int[]{(Integer) args[CollectionLogConstants.ARG_INDEX_ITEM_ID], qty};
	}
}

package com.clansocket.tracking.inventory;

import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
final class Pending
{
	final String label;
	final int[] ids;
	final int[] qtys;
	final int[] slots;
}

package com.clansocket.tracking.inventory;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import net.runelite.api.ItemContainer;

import com.clansocket.bus.Hashes;
import com.clansocket.protocol.inventory.Item;

final class ItemSnapshots
{
	private ItemSnapshots() {
	}

	static List<Item> fromContainer(final ItemContainer ic, final ItemNames itemNames, final int[] tabBoundaries)
	{
		final net.runelite.api.Item[] raw = ic.getItems();
		final List<Item> items = new ArrayList<>(raw.length);
		for (int slot = 0; slot < raw.length; slot++)
		{
			final net.runelite.api.Item it = raw[slot];
			final int id = it.getId();
			if (id <= 0 || it.getQuantity() <= 0 || itemNames.isPlaceholder(id))
			{
				continue;
			}
			final Integer tab = tabBoundaries == null ? null : Integer.valueOf(tabForSlot(slot, tabBoundaries));
			items.add(new Item(id, it.getQuantity(), itemNames.resolve(id), itemNames.resolvePrice(id), slot, tab));
		}
		return Collections.unmodifiableList(items);
	}

	static int tabForSlot(final int slot, final int[] tabBoundaries)
	{
		for (int t = 0; t < tabBoundaries.length; t++)
		{
			if (slot < tabBoundaries[t])
			{
				return t + 1;
			}
		}
		return 0;
	}

	static Pending rawSnapshot(final String label, final ItemContainer ic)
	{
		final net.runelite.api.Item[] raw = ic.getItems();
		final int[] ids = new int[raw.length];
		final int[] qtys = new int[raw.length];
		final int[] slots = new int[raw.length];
		int idx = 0;
		for (int slot = 0; slot < raw.length; slot++)
		{
			final net.runelite.api.Item it = raw[slot];
			if (it.getId() <= 0 || it.getQuantity() <= 0)
			{
				continue;
			}
			ids[idx] = it.getId();
			qtys[idx] = it.getQuantity();
			slots[idx] = slot;
			idx++;
		}
		return new Pending(label, Arrays.copyOf(ids, idx), Arrays.copyOf(qtys, idx), Arrays.copyOf(slots, idx));
	}

	static List<Item> resolve(final Pending p, final ItemNames itemNames)
	{
		final List<Item> items = new ArrayList<>(p.ids.length);
		for (int i = 0; i < p.ids.length; i++)
		{
			final int id = p.ids[i];
			items.add(new Item(id, p.qtys[i], itemNames.resolve(id), itemNames.resolvePrice(id), p.slots[i], null));
		}
		return Collections.unmodifiableList(items);
	}

	static String hashByIdQty(final List<Item> items)
	{
		return Long.toHexString(Hashes.pairsLong(items, i -> i.id, i -> i.qty));
	}

	static long rawHashLong(final String label, final int[] ids, final int[] qtys, final int[] slots)
	{
		return Hashes.rollingArrays(label.hashCode(), ids, qtys, slots);
	}
}

package com.clansocket.tracking.inventory;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.ClanSocketConfig;
import com.clansocket.bus.Hashes;
import com.clansocket.bus.primitive.LatchedSnapshotTracker;
import com.clansocket.protocol.common.Payload;
import com.clansocket.protocol.inventory.RunePouchSlot;

@Singleton
public class RunePouchTracker extends LatchedSnapshotTracker<Long>
{
	@Inject
	private ItemNames itemNames;
	@Inject
	private ClanSocketConfig config;

	@Override
	protected void emitFreshSnapshot()
	{
		if (!config.streamRunePouch())
		{
			return;
		}
		latch.reset();
		readAndEmit();
	}

	@Subscribe
	public void onVarbitChanged(final VarbitChanged event)
	{
		if (!config.streamRunePouch())
		{
			return;
		}
		if (!InventoryConstants.RUNE_POUCH_WATCHED.contains(event.getVarbitId()) || !isLoggedIn())
		{
			return;
		}
		readAndEmit();
	}

	private void readAndEmit()
	{
		final EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runeEnum != null)
		{
			emitIfChanged(runeEnum);
		}
	}

	private void emitIfChanged(final EnumComposition runeEnum)
	{
		final int slotCount = InventoryConstants.RUNE_POUCH_TYPE_VARBITS.length;
		final List<RunePouchSlot> slots = new ArrayList<>(slotCount);
		final long sig = collectSlots(runeEnum, slots, slotCount);
		if (!latch.update(sig))
		{
			return;
		}
		batcher.enqueue(
		        new Payload("rune_pouch", "hash", Long.toHexString(sig), "slots", Collections.unmodifiableList(slots)));
	}

	private long collectSlots(final EnumComposition runeEnum, final List<RunePouchSlot> out, final int slotCount)
	{
		long sig = 1L;
		for (int i = 0; i < slotCount; i++)
		{
			sig = sig * Hashes.HASH_PRIME + client.getVarbitValue(InventoryConstants.RUNE_POUCH_QTY_VARBITS[i]);
			sig = sig * Hashes.HASH_PRIME + client.getVarbitValue(InventoryConstants.RUNE_POUCH_TYPE_VARBITS[i]);
			final RunePouchSlot slot = resolveSlot(runeEnum, i);
			if (slot != null)
			{
				out.add(slot);
			}
		}
		return sig;
	}

	private RunePouchSlot resolveSlot(final EnumComposition runeEnum, final int index)
	{
		final int qty = client.getVarbitValue(InventoryConstants.RUNE_POUCH_QTY_VARBITS[index]);
		final int runeKey = client.getVarbitValue(InventoryConstants.RUNE_POUCH_TYPE_VARBITS[index]);
		if (qty <= 0 || runeKey <= 0)
		{
			return null;
		}
		final int itemId = runeEnum.getIntValue(runeKey);
		if (itemId <= 0)
		{
			return null;
		}
		return new RunePouchSlot(index, itemId, qty, itemNames.resolve(itemId), itemNames.resolvePrice(itemId));
	}
}

package com.clansocket.tracking.inventory;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.client.game.ItemManager;

import com.clansocket.bus.primitive.IntIntMap;
import com.clansocket.bus.primitive.IntObjectMap;

@Singleton
public final class ItemNames
{
	private static final int PRICE_MISS = Integer.MIN_VALUE;

	private final ItemManager itemManager;
	private final IntObjectMap<String> nameCache = new IntObjectMap<>();
	private final IntIntMap priceCache = new IntIntMap(16, PRICE_MISS);

	@Inject
	public ItemNames(final ItemManager itemManager) {
		this.itemManager = itemManager;
	}

	public String resolve(final int itemId)
	{
		String name = nameCache.get(itemId);
		if (name != null)
		{
			return name;
		}
		name = fetchName(itemId);
		if (name != null)
		{
			nameCache.put(itemId, name);
		}
		return name;
	}

	public int resolvePrice(final int itemId)
	{
		int cached = priceCache.get(itemId);
		if (cached != PRICE_MISS)
		{
			return cached;
		}
		cached = fetchPrice(itemId);
		priceCache.put(itemId, cached);
		return cached;
	}

	public boolean isPlaceholder(final int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1;
		} catch (final RuntimeException t)
		{
			return false;
		}
	}

	public void clear()
	{
		nameCache.clear();
		priceCache.clear();
	}

	private String fetchName(final int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getName();
		} catch (final RuntimeException t)
		{
			return null;
		}
	}

	private int fetchPrice(final int itemId)
	{
		try
		{
			return itemManager.getItemPrice(itemId);
		} catch (final RuntimeException t)
		{
			return 0;
		}
	}
}

package com.clansocket.tracking.inventory;

import java.util.Collections;
