package com.clansocket.tracking.identity;

import java.util.List;
import java.util.stream.Collectors;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.WorldService;
import net.runelite.http.api.worlds.World;
import net.runelite.http.api.worlds.WorldResult;

import com.clansocket.ClanSocket;
import com.clansocket.ClanSocketConstants;
import com.clansocket.bus.EventBatcher;
import com.clansocket.chat.GameChatEmitter;
import com.clansocket.protocol.common.Payload;

import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
final class IdentityEmitter
{
	@Inject
	private Client client;
	@Inject
	private EventBatcher batcher;
	@Inject
	private ClanSocket socket;
	@Inject
	private GameChatEmitter chatEmitter;
	@Inject
	private ClanResolver clanResolver;
	@Inject
	private WorldService worldService;

	boolean emit(final Player local, final String sessionStartIso, final boolean sessionReminderSent)
	{
		final long accountHashLong = client.getAccountHash();
		if (accountHashLong == -1L)
		{
			return sessionReminderSent;
		}
		final Payload payload = buildIdentity(local, sessionStartIso, accountHashLong);
		batcher.enqueue(payload);
		if (!sessionReminderSent)
		{
			chatEmitter.sessionReminder((String) payload.get("clanName"), (String) payload.get("clanRank"),
			        socket.isConnected());
			return true;
		}
		return sessionReminderSent;
	}

	private Payload buildIdentity(final Player local, final String sessionStartIso, final long accountHashLong)
	{
		final String rsn = local.getName();
		final int world = client.getWorld();
		final List<String> worldTypeNames = client.getWorldType().stream().map(WorldType::name)
		        .collect(Collectors.toUnmodifiableList());
		final ClanInfo clan = clanResolver.resolve(rsn);
		final Payload payload = new Payload("identity", "rsn", rsn, "accountHash",
		        Long.toUnsignedString(accountHashLong), "accountType", resolveAccountType(), "world", world,
		        "worldTypes", worldTypeNames, "activity", resolveActivity(world), "clanName", clan.name, "clanRank",
		        clan.rank, "clanJoinedAt", clan.joinedAt, "clanMemberCount", clan.memberCount, "clanOnlineCount",
		        clan.onlineCount, "sessionStart", sessionStartIso, "pluginVersion", ClanSocketConstants.PLUGIN_VERSION,
		        "schemaVersion", ClanSocketConstants.PROTOCOL_VERSION);
		log.debug("ClanSocket identity rsn={} acct={} world={} clan={}/{} joined={} members={}/{} types={}", rsn,
		        payload.get("accountHash"), world, clan.name, clan.rank, clan.joinedAt, clan.memberCount,
		        clan.onlineCount, worldTypeNames);
		return payload;
	}

	private String resolveAccountType()
	{
		final int idx = client.getVarbitValue(VarbitID.IRONMAN);
		if (idx >= 0 && idx < IdentityConstants.ACCOUNT_TYPE_NAMES.length)
		{
			return IdentityConstants.ACCOUNT_TYPE_NAMES[idx];
		}
		return "UNKNOWN_" + idx;
	}

	private String resolveActivity(final int currentWorld)
	{
		final WorldResult result = worldService.getWorlds();
		if (result == null)
		{
			return null;
		}
		final World w = result.findWorld(currentWorld);
		return w != null ? w.getActivity() : null;
	}
}

package com.clansocket.tracking.identity;

import java.time.Instant;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WorldChanged;
import net.runelite.client.eventbus.Subscribe;

import com.clansocket.bus.AbstractStateTracker;
import com.clansocket.bus.primitive.WarmupCounter;

@Singleton
public class IdentityTracker extends AbstractStateTracker
{
	private enum Phase
	{
		INITIAL, AWAITING_LOGIN, WARMUP, ACTIVE
	}

	@Inject
	private IdentityEmitter emitter;

	private final WarmupCounter warmup = new WarmupCounter(IdentityConstants.CLAN_SETTINGS_TICK_WAIT);
	private final WarmupCounter reassert = new WarmupCounter(IdentityConstants.IDENTITY_REASSERT_TICKS);

	private volatile Phase phase = Phase.INITIAL;
	private volatile boolean sessionReminderSent;
	private volatile String sessionStartIso;

	@Override
	protected void onLoginScreen()
	{
		phase = Phase.AWAITING_LOGIN;
		warmup.reset();
		reassert.reset();
		sessionReminderSent = false;
		sessionStartIso = null;
	}

	@Override
	protected void onLoggedIn()
	{
		if (phase != Phase.AWAITING_LOGIN)
		{
			return;
		}
		phase = Phase.WARMUP;
		warmup.reset();
		if (sessionStartIso == null)
		{
			sessionStartIso = Instant.now().toString();
		}
	}

	@Override
	protected void onOtherGameState(final GameState state)
	{
		if ((state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		        && (phase == Phase.ACTIVE || phase == Phase.WARMUP))
		{
			phase = Phase.WARMUP;
			warmup.reset();
		}
	}

	@Override
	public void resetForReconnect()
	{
		phase = Phase.WARMUP;
		warmup.skipToReady();
		reassert.reset();
	}

	@Subscribe
	public void onGameTick(final GameTick tick)
	{
		if (phase == Phase.WARMUP)
		{
			attemptInitialEmit();
		} else if (phase == Phase.ACTIVE && isLoggedIn())
		{
			maybeReassert();
		}
	}

	private void attemptInitialEmit()
	{
		final Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return;
		}
		if (!warmup.tickAndReady())
		{
			return;
		}
		sessionReminderSent = emitter.emit(local, sessionStartIso, sessionReminderSent);
		phase = Phase.ACTIVE;
		reassert.reset();
	}

	private void maybeReassert()
	{
		if (!reassert.tickAndReady())
		{
			return;
		}
		reassert.reset();
		final Player local = client.getLocalPlayer();
		if (local != null && local.getName() != null)
		{
			sessionReminderSent = emitter.emit(local, sessionStartIso, sessionReminderSent);
		}
	}

	@Subscribe
	public void onWorldChanged(final WorldChanged event)
	{
		phase = Phase.WARMUP;
		warmup.reset();
		reassert.reset();
	}
}

package com.clansocket.tracking.identity;

import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
final class ClanInfo
{
	static final ClanInfo EMPTY = new ClanInfo(null, null, null, null, null);

	final String name;
	final String rank;
	final String joinedAt;
	final Integer memberCount;
	final Integer onlineCount;
}

package com.clansocket.tracking.identity;

import java.util.function.Supplier;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Client;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanID;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;

import com.clansocket.util.Strings;

import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public final class ClanResolver
{
	private final Client client;

	@Inject
	public ClanResolver(final Client client) {
		this.client = client;
	}

	public ClanInfo resolve(final String rsn)
	{
		return safe(() ->
		{
			final ClanSettings clan = client.getClanSettings(ClanID.CLAN);
			if (clan == null)
			{
				return ClanInfo.EMPTY;
			}
			final ClanMember me = clan.findMember(rsn);
			final String rank = resolveRank(clan, me);
			final String joinedAt = me != null && me.getJoinDate() != null ? me.getJoinDate().toString() : null;
			final Integer memberCount = clan.getMembers() != null ? clan.getMembers().size() : null;
			final ClanChannel channel = client.getClanChannel(ClanID.CLAN);
			final Integer onlineCount = channel != null && channel.getMembers() != null
			        ? channel.getMembers().size()
			        : null;
			return new ClanInfo(clan.getName(), rank, joinedAt, memberCount, onlineCount);
		}, ClanInfo.EMPTY, "clan resolve");
	}

	public String memberRank(final String rsn)
	{
		return safe(() ->
		{
			final ClanSettings clan = client.getClanSettings(ClanID.CLAN);
			return clan == null ? null : resolveRank(clan, clan.findMember(rsn));
		}, null, "clan rank lookup");
	}

	public String currentClanName()
	{
		return safe(() ->
		{
			final ClanChannel channel = client.getClanChannel();
			if (channel != null && channel.getName() != null)
			{
				return channel.getName();
			}
			final ClanSettings settings = client.getClanSettings(ClanID.CLAN);
			return settings == null ? null : settings.getName();
		}, null, "clan name lookup");
	}

	public static String rankTitle(final ClanSettings clan, final ClanRank rank)
	{
		if (rank == null)
		{
			return null;
		}
		final ClanTitle title = clan.titleForRank(rank);
		return title != null && Strings.isNotEmpty(title.getName()) ? title.getName() : "rank-" + rank.getRank();
	}

	private static String resolveRank(final ClanSettings clan, final ClanMember me)
	{
		return me == null ? null : rankTitle(clan, me.getRank());
	}

	private static <T> T safe(final Supplier<T> action, final T fallback, final String label)
	{
		try
		{
			return action.get();
		} catch (final RuntimeException t)
		{
			log.debug("ClanSocket {} failed", label, t);
			return fallback;
		}
	}
}

