package com.clansocket.world;

final class WorldConstants
{
	static final String LOCATIONS_RESOURCE = "locations.json";
	static final int CHUNK_PAIR_SIZE = 2;
	static final int RX_SHIFT = 8;
	static final int RY_MASK = 0xFF;
	static final int PACK_SHIFT = 32;
	static final long PACK_MASK = 0xFFFFFFFFL;

	private WorldConstants() {
	}
}

package com.clansocket.world;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;

import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public final class AreaResolver
{
	private final Gson gson;
	private Map<Long, String> regionToArea;

	@Inject
	AreaResolver(final Gson gson) {
		this.gson = gson;
	}

	public String resolve(final int regionId)
	{
		if (regionToArea == null)
		{
			regionToArea = load();
		}
		return regionToArea.get(regionKey(regionId >> WorldConstants.RX_SHIFT, regionId & WorldConstants.RY_MASK));
	}

	private static long regionKey(final int rx, final int ry)
	{
		return (((long) rx) << WorldConstants.PACK_SHIFT) | (ry & WorldConstants.PACK_MASK);
	}

	private Map<Long, String> load()
	{
		final Map<Long, String> out = new HashMap<>();
		try (final InputStream is = AreaResolver.class.getResourceAsStream("/" + WorldConstants.LOCATIONS_RESOURCE))
		{
			if (is == null)
			{
				log.warn("ClanSocket area lookup: {} not found on classpath; area names disabled",
				        WorldConstants.LOCATIONS_RESOURCE);
				return out;
			}
			populate(out, is);
		} catch (final IOException | JsonParseException t)
		{
			log.warn("ClanSocket area lookup: load failed: {}", t.getMessage());
		}
		log.info("ClanSocket area lookup: loaded {} region→area mappings", out.size());
		return out;
	}

	private void populate(final Map<Long, String> out, final InputStream is) throws IOException
	{
		try (final Reader reader = new InputStreamReader(is))
		{
			final Type type = new TypeToken<Map<String, List<List<Integer>>>>()
			{
			}.getType();
			final Map<String, List<List<Integer>>> data = gson.fromJson(reader, type);
			if (data == null)
			{
				return;
			}
			for (final Map.Entry<String, List<List<Integer>>> entry : data.entrySet())
			{
				addEntries(out, entry.getKey(), entry.getValue());
			}
		}
	}

	private static void addEntries(final Map<Long, String> out, final String name, final List<List<Integer>> chunks)
	{
		for (final List<Integer> chunk : chunks)
		{
			if (chunk == null || chunk.size() != WorldConstants.CHUNK_PAIR_SIZE)
			{
				continue;
			}
			out.put(regionKey(chunk.get(0), chunk.get(1)), name);
		}
	}
}

package com.clansocket.util;

import com.clansocket.ClanSocketConstants;

public final class Urls
{
	private Urls() {
	}

	public static String host(final String url)
	{
		final String afterScheme = stripScheme(url);
		if (Strings.isEmpty(afterScheme))
		{
			return afterScheme;
		}
		final int slash = afterScheme.indexOf('/');
		return slash < 0 ? afterScheme : afterScheme.substring(0, slash);
	}

	private static String stripScheme(final String url)
	{
		if (Strings.isEmpty(url))
		{
			return url;
		}
		final int delim = url.indexOf(ClanSocketConstants.SCHEME_DELIM);
		return delim < 0 ? url : url.substring(delim + ClanSocketConstants.SCHEME_DELIM_LEN);
	}
}

package com.clansocket.util;

import java.util.function.ToIntFunction;

public final class Money
{
	private Money() {
	}

	public static <T> long sumGp(final Iterable<T> items, final ToIntFunction<T> qty, final ToIntFunction<T> price)
	{
		long total = 0L;
		for (final T it : items)
		{
			total += (long) qty.applyAsInt(it) * price.applyAsInt(it);
		}
		return total;
	}
}

package com.clansocket.util;

import java.util.function.Function;

public final class NumberInput
{
	private NumberInput() {
	}

	public static int parseIntOr(final String s, final int fallback)
	{
		return parseOr(s, Integer::parseInt, fallback);
	}

	private static <T> T parseOr(final String s, final Function<String, T> parser, final T fallback)
	{
		if (Strings.isBlank(s))
		{
			return fallback;
		}
		try
		{
			return parser.apply(s.trim());
		} catch (final NumberFormatException ignored)
		{
			return fallback;
		}
	}
}

package com.clansocket.util;

public final class Strings
{
	private Strings() {
	}

	public static boolean isEmpty(final String s)
	{
		return s == null || s.isEmpty();
	}

	public static boolean isNotEmpty(final String s)
	{
		return s != null && !s.isEmpty();
	}

	public static boolean isBlank(final String s)
	{
		return s == null || s.isBlank();
	}
}

